        default = false, onToggle = function(v)
            if v then newFx("cc1", "ColorCorrectionEffect"); newFx("cc2", "ColorCorrectionEffect"); newFx("cc3", "ColorCorrectionEffect"); applyGrade()
            else killFx("cc1"); killFx("cc2"); killFx("cc3") end
        end,
        settings = {
            { type = "slider", name = "Contrast",   key = "c", min = -1, max = 1, step = 0.01,  default = DEFAULTS.cc1C, onChange = function(v) sv.cc1C = v; applyGrade() end, onCreate = function(h) handles.cc1C = h end },
            { type = "slider", name = "Saturation", key = "s", min = -1, max = 1, step = 0.01,  default = DEFAULTS.cc1S, onChange = function(v) sv.cc1S = v; applyGrade() end, onCreate = function(h) handles.cc1S = h end },
            { type = "slider", name = "Brightness", key = "b", min = -1, max = 1, step = 0.001, default = DEFAULTS.cc1B, onChange = function(v) sv.cc1B = v; applyGrade() end, onCreate = function(h) handles.cc1B = h end },
        },
    }).root)

    box:add(feature.declare({
        id = "aesthetic.motionblur", name = "Motion Blur",
        description = "Camera blur scaled by how fast you turn. Client-side BlurEffect on the camera -- avoid on strict-AC games.",
        default = false, onToggle = function(v) enableBlur(v) end,
        settings = {
            { type = "slider", name = "Amount", key = "a", min = 0, max = 30, step = 1, default = DEFAULTS.blurAmount, onChange = function(v) sv.blurAmount = v end, onCreate = function(h) handles.blurAmount = h end },
        },
    }).root)

    shaderBooting = false
    log.info("Aesthetic module registered")
end

function Aesthetic.destroy()
    if enforceConn then enforceConn:Disconnect(); enforceConn = nil end
    revertFullbright(); revertFog(); revertTime(); revertFov()
    shaderTeardown()
end

return Aesthetic
end

_MODULES["modules.misc.faketab"] = function()
-- Fake Tab: reproduces the PvP effect of alt-tabbing ("tabbing") without the
-- downside. When you really alt-tab, Roblox throttles the client to ~0 FPS, your
-- character stops replicating movement, and to everyone else you're frozen in
-- place (and you stop eating knockback / combos). The useful half of that is the
-- freeze-in-place desync; the painful half is that YOU can't see at 0 FPS. This
-- gives you the freeze without the blackout -- camera / vision / aim stay live.
--
-- Mechanism: anchor the HEAD. In an R6/R15 rig every part is rigidly joined
-- (Motor6D) up to the head, so anchoring the head pins the whole assembly in
-- place. It's the head specifically that gives the clean tab-freeze in the games
-- this is used in -- anchoring the HumanoidRootPart tends to disturb the Humanoid
-- (it's the assembly root) / get noticed, whereas the head doesn't. The anchored
-- state replicates (we own our character), so others see us frozen and external
-- forces can't shove us.
--
-- A light Heartbeat keeps it anchored: it re-anchors the new head after a respawn
-- and re-asserts if the game unanchors us. It deliberately does NOT yield, so it
-- sidesteps Wave's "task.wait in a respawn signal may not resume" quirk
-- ([[feedback_executor_signal_taskwait]]). Anchored=true is still a property tell
-- -- this makes no anti-cheat-safety claims ([[feedback_adonis_detection]]).

local RunService = game:GetService("RunService")
local Players    = game:GetService("Players")
local LP         = Players.LocalPlayer

local feature = require("ui.feature")
local log     = require("core.log")
local notify  = require("ui.notify")

local FakeTab = {}

local enabled  = false
local anchored = nil   -- the BasePart we currently hold anchored (so we restore exactly it)
local hbConn   = nil   -- the Heartbeat maintainer (live only while enabled)

-- The part we freeze: Head first (the tab-freeze part), else fall back to the
-- root / any BasePart so the feature still does something on an odd rig.
local function freezePart(char)
    if not char then return nil end
    return char:FindFirstChild("Head")
        or char:FindFirstChild("HumanoidRootPart")
        or char:FindFirstChild("Torso")
        or char:FindFirstChild("UpperTorso")
        or char:FindFirstChildWhichIsA("BasePart")
end

local function release()
    if anchored then pcall(function() anchored.Anchored = false end); anchored = nil end
end

-- Keep the head anchored. Picks up a NEW body after a respawn (the old anchored
-- head died with the old character) and re-asserts if something unanchored us --
-- all without yielding, so the Wave signal/taskwait quirk can't strand it.
local function tick()
    if not enabled then return end
    local char = LP.Character
    local part = freezePart(char)
    if not part then return end
    if anchored ~= part then                 -- first anchor, or a fresh body after respawn
        if anchored then pcall(function() anchored.Anchored = false end) end
        anchored = part
    end
    if not part.Anchored then pcall(function() part.Anchored = true end) end
    -- stop the walk animation from moonwalking in place while we're pinned
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then pcall(function() hum:Move(Vector3.zero, false) end) end
end

local function setActive(v)
    v = v and true or false
    if enabled == v then return end

    if v then
        if not LP.Character then
            notify.warn("Fake Tab: no character to freeze")
            return   -- leave disabled; toggling again once spawned works
        end
        enabled = true
        if not hbConn then hbConn = RunService.Heartbeat:Connect(tick) end
        tick()   -- anchor immediately; the Heartbeat maintains it from here
        notify.success("Fake Tab ON -- frozen (head anchored), FPS untouched")
    else
        enabled = false
        if hbConn then pcall(function() hbConn:Disconnect() end); hbConn = nil end
        release()
        notify.info("Fake Tab OFF -- thawed")
    end
end

function FakeTab.register(box)
    box:add(feature.declare({
        id          = "misc.faketab",
        name        = "Fake Tab",
        description = "Reproduces alt-tab \"tabbing\": freezes your character in place by anchoring your head -- the whole rig is rigidly joined to it, so you lock up and stop replicating movement (others see you stuck still and you stop taking knockback / combos) -- but WITHOUT dropping your own FPS to zero, so you keep full vision, camera and aim. Survives respawns while it's on. Bind a key below to flick it on/off like real alt-tabbing. You can't move while frozen -- toggle off to resume.",
        default     = false,
        onToggle    = setActive,
    }).root)

    log.info("Fake Tab feature registered")
end

function FakeTab.destroy()
    enabled = false
    if hbConn then pcall(function() hbConn:Disconnect() end); hbConn = nil end
    release()
end

return FakeTab
end

_MODULES["modules.misc.freecam"] = function()
-- Free Cam: detaches the camera from your character and flies it around freely
-- while the body stays put.
--
-- Camera technique borrowed from the OpenGui freecam: never touch CameraType. Spawn
-- an invisible part, point camera.CameraSubject at it, and fly the part. The game's
-- own camera keeps running and just follows the part, so mouse-look is the native
-- camera (no cursor lock, this menu stays clickable) and nothing fights us.
--
-- Keeping the body still: we DISABLE THE PLAYER'S CONTROL MODULE
-- (PlayerModule:GetControls():Disable()) -- so WASD/jump simply stop driving the
-- character. No anchoring, no WalkSpeed/JumpPower changes; the body just stands there
-- intact and the controls are re-enabled on exit. Pantheon's global `require` is the
-- bundler shim ([[feedback_pantheon_require_shim]]), so we reach Roblox's real
-- `require` via getrenv() to load the PlayerModule. If that isn't available we fall
-- back to cancelling the body's velocity each frame (still no anchor / no speed edit).

local RunService       = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Players          = game:GetService("Players")
local Workspace        = game:GetService("Workspace")
local LP               = Players.LocalPlayer

local feature = require("ui.feature")
local log     = require("core.log")
local notify  = require("ui.notify")

local FreeCam = {}

local enabled    = false
local speed      = 5       -- per-frame move magnitude (pre-smoothing)
local smoothness = 0.2     -- 0..1 lerp factor; lower = floatier, higher = snappier

local camPart  = nil       -- the invisible part the camera follows
local moveCF   = nil       -- smoothed local-space move offset (a CFrame, lerped)
local dir      = { w = false, a = false, s = false, d = false, up = false, down = false }

local controls       = nil    -- PlayerModule Controls, while we hold it disabled
local controlsFailed = false  -- couldn't get controls -> use the per-frame fallback

local renderConn, beganConn, endedConn, charConn

-- which fly flag each key drives (Space/Q rise, Ctrl/E drop)
local KEY = {
    [Enum.KeyCode.W] = "w", [Enum.KeyCode.A] = "a",
    [Enum.KeyCode.S] = "s", [Enum.KeyCode.D] = "d",
    [Enum.KeyCode.Space] = "up",   [Enum.KeyCode.Q] = "up",
    [Enum.KeyCode.LeftControl] = "down", [Enum.KeyCode.E] = "down",
}

local function rootOf(char)
    if not char then return nil end
    return char.PrimaryPart
        or char:FindFirstChild("HumanoidRootPart")
        or char:FindFirstChildWhichIsA("BasePart")
end

-- Roblox's REAL require (our global `require` is the bundler shim, which can't load a
-- ModuleScript). getrenv() exposes the real global env on Wave/most executors.
local function getControls()
    local ps = LP:FindFirstChild("PlayerScripts")
    local pm = ps and ps:FindFirstChild("PlayerModule")
    if not pm then return nil end
    local rr
    pcall(function() if getrenv then rr = getrenv().require end end)
    if type(rr) ~= "function" then return nil end
    local ok, mod = pcall(rr, pm)
    if not ok or type(mod) ~= "table" then return nil end
    local ok2, c = pcall(function() return mod:GetControls() end)
    if ok2 and c then return c end
    return nil
end

-- Stop the body walking by disabling the control module (NOT anchor / NOT speed).
local function freezeControls()
    if not controls then controls = getControls() end
    if controls then
        pcall(function() controls:Disable() end)
        controlsFailed = false
    else
        controlsFailed = true   -- step() will damp velocity instead
    end
end

local function thawControls()
    if controls then pcall(function() controls:Enable() end); controls = nil end
    controlsFailed = false
end

-- Fallback ONLY when the controls module is unreachable: cancel the body's own motion
-- each frame -- still no anchoring and no WalkSpeed/JumpPower edits.
local function dampBody()
    local char = LP.Character
    local hrp  = char and rootOf(char)
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if hrp then pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero end) end
    if hum then pcall(function() hum:Move(Vector3.zero, false) end) end
end

local function step()
    if not enabled then return end
    local camera = Workspace.CurrentCamera
    if not camera or not camPart then return end

    camera.CameraSubject = camPart        -- re-assert: the camera follows our part
    if controlsFailed then dampBody() end

    -- aim the part down the camera's look so WASD is view-relative
    camPart.CFrame = CFrame.new(camPart.CFrame.Position, (camera.CFrame * CFrame.new(0, 0, -100)).Position)

    -- assemble the local-space move from held keys (-Z is forward)
    local x, y, z = 0, 0, 0
    if dir.w    then z = z - speed end
    if dir.s    then z = z + speed end
    if dir.a    then x = x - speed end
    if dir.d    then x = x + speed end
    if dir.up   then y = y + speed end
    if dir.down then y = y - speed end

    -- smooth the input, then ease the part toward part * move (OpenGui's feel)
    moveCF = moveCF:Lerp(CFrame.new(x, y, z), smoothness)
    camPart.CFrame = camPart.CFrame:Lerp(camPart.CFrame * moveCF, smoothness)
end

local function setActive(v)
    v = v and true or false
    if enabled == v then return end

    if v then
        local camera = Workspace.CurrentCamera
        if not camera then
            notify.warn("Free Cam: no camera available")
            return
        end

        enabled = true
        moveCF  = CFrame.new()
        dir     = { w = false, a = false, s = false, d = false, up = false, down = false }

        camPart = Instance.new("Part")
        camPart.Name         = "Camera"
        camPart.Transparency = 1
        camPart.Anchored     = true
        camPart.CanCollide   = false
        camPart.CanTouch     = false
        camPart.CanQuery     = false
        camPart.CFrame       = camera.CFrame
        camPart.Parent       = Workspace

        freezeControls()
        -- kill any residual walk momentum once so the body doesn't drift on start
        pcall(function() local r = rootOf(LP.Character); if r then r.AssemblyLinearVelocity = Vector3.zero end end)
        camera.CameraSubject = camPart

        renderConn = RunService.RenderStepped:Connect(step)
        beganConn  = UserInputService.InputBegan:Connect(function(input, gameProcessed)
            if gameProcessed then return end          -- ignore typing / UI input
            local k = KEY[input.KeyCode]
            if k then dir[k] = true end
        end)
        endedConn  = UserInputService.InputEnded:Connect(function(input)
            local k = KEY[input.KeyCode]               -- never gate release (no stuck keys)
            if k then dir[k] = false end
        end)
        -- re-disable the controls after a respawn (no yield -> dodges the Wave
        -- respawn/taskwait quirk [[feedback_executor_signal_taskwait]])
        charConn = LP.CharacterAdded:Connect(function()
            if enabled then freezeControls() end
        end)

        notify.success("Free Cam ON -- WASD + Space/Ctrl to fly, mouse to look")
    else
        enabled = false
        if renderConn then pcall(function() renderConn:Disconnect() end); renderConn = nil end
        if beganConn  then pcall(function() beganConn:Disconnect()  end); beganConn  = nil end
        if endedConn  then pcall(function() endedConn:Disconnect()  end); endedConn  = nil end
        if charConn   then pcall(function() charConn:Disconnect()   end); charConn   = nil end

        thawControls()
        local camera = Workspace.CurrentCamera
        if camera then
            local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            pcall(function() camera.CameraSubject = hum end)   -- hand the camera back
        end
        if camPart then pcall(function() camPart:Destroy() end); camPart = nil end

        notify.info("Free Cam OFF -- camera returned")
    end
end

function FreeCam.register(box)
    box:add(feature.declare({
        id          = "misc.freecam",
        name        = "Free Cam",
        description = "Detaches the camera from your character and lets you fly it around freely while your body stays put where you left it. Look around with your mouse exactly like normal (it rides the game's own camera -- no cursor lock, this menu stays clickable), and fly with WASD relative to where you're looking, Space / Q to rise and Left-Ctrl / E to drop. \"Speed\" sets how fast it flies, \"Smoothness\" how floaty (lower = driftier, higher = snappier). While flying, your character's movement controls are simply switched off so the body stands still -- no anchoring, no walkspeed changes -- and switched back on when you exit. Survives respawns while it's on.",
        default     = false,
        onToggle    = setActive,
        settings    = {
            { type = "slider", name = "Speed", key = "speed",
              min = 1, max = 50, step = 1, default = 5,
              onChange = function(v) speed = v end },
            { type = "slider", name = "Smoothness", key = "smoothness",
              min = 0.05, max = 1, step = 0.05, default = 0.2,
              onChange = function(v) smoothness = v end },
        },
    }).root)

    log.info("Free Cam feature registered")
end

function FreeCam.destroy()
    setActive(false)
end

return FreeCam
end

_MODULES["modules.misc.init"] = function()
-- Miscellaneous: catch-all menu for standalone utility scripts that don't fit
-- the aim / aesthetic / tech buckets. Each script self-contains its own feature
-- declaration and lifecycle; this just owns the shared container and fans
-- register()/destroy() out to them. Add a new script: require it here, call its
-- .register(box) in Misc.register, and its .destroy() in Misc.destroy.

local container = require("ui.container")
local window    = require("ui.window")
local log       = require("core.log")

local faketab   = require("modules.misc.faketab")
local freecam   = require("modules.misc.freecam")

local Misc = {}

local scripts = { faketab, freecam }

function Misc.register()
    local box = container.new(window.parent(), "Miscellaneous")
    for _, m in ipairs(scripts) do
        local ok, err = pcall(function() m.register(box) end)
        if not ok then log.warn("misc script register failed: " .. tostring(err)) end
    end
    log.info("Miscellaneous module registered")
end

function Misc.destroy()
    for _, m in ipairs(scripts) do
        pcall(function() if m.destroy then m.destroy() end end)
    end
end

return Misc
end

_MODULES["modules.addons.api"] = function()
-- Addon-facing API.
--
-- Every addon script is run with a global `Pantheon` (this module's .Pantheon
-- table) -- the same idea as Infinite Yield handing addons its command API. An
-- addon's ONLY required call is:
--
--     local addon = Pantheon.register({
--         name        = "My Addon",
--         description = "what it does",
--         scope       = "universal",        -- or a PlaceId/GameId number, a list
--                                           --   of them, or "char:CharacterName"
--         setup = function(ctx)
--             -- Runs ONLY when the addon is ACTIVE (enabled in the Addons menu
--             -- AND its scope matches the current game). Build the addon's UI
--             -- and start its logic here -- nothing game-specific should run at
--             -- file top level, so a disabled / wrong-game addon stays inert.
--             local m = ctx:menu()                       -- a navigator menu (its own panel)
--             m:toggle("Cool Thing", { default = false, description = "..." }, function(on) ... end)
--             m:button("Do It", function() ... end)
--             m:slider("Speed", { min = 0, max = 100, default = 50 }, function(v) ... end)
--             m:keybind("Trigger", { default = "G" }, function() ... end)
--             ctx:connect(game:GetService("RunService").Heartbeat, function(dt) ... end)  -- auto-disconnected
--             ctx:onUnload(function() ... end)           -- runs when toggled off / reloaded / on re-execute
--         end,
--     })
--
-- Everything built through `ctx` (menus, features, keybinds, connections) is
-- tracked so the Addons manager can fully tear the addon down when you toggle it
-- off, reload it, or re-execute Pantheon -- no leaks, no orphan menus.
--
-- Power users can also reach the raw building blocks on the Pantheon table
-- (Pantheon.feature, .components, .container, .notify, .persist, .keybinds, ...).

local feature    = require("ui.feature")
local container  = require("ui.container")
local components = require("ui.components")
local window     = require("ui.window")
local notify     = require("ui.notify")
local keybinds   = require("core.keybinds")
local persist    = require("core.persist")
local log        = require("core.log")

local API = {}

-- Defs registered during the current file's load pass. init.lua sets the current
-- file, runs the chunk (which calls Pantheon.register), then takes the list.
local registered  = {}
local currentFile = nil

function API.setCurrentFile(name) currentFile = name end
function API.takeRegistered()
    local out = registered
    registered = {}
    return out
end

local function toKeyCode(k)
    if k == nil then return nil end
    if typeof(k) == "EnumItem" then return k end
    local ok, kc = pcall(function() return Enum.KeyCode[tostring(k)] end)
    return (ok and kc) or nil
end

-- ===== per-addon context =====
-- Built at ACTIVATION (enabled + scope match). Tracks everything the addon makes
-- so :destroy() (called by the manager) reverses all of it.
function API.makeContext(def)
    local ctx = { name = def.name, id = def.id, scope = def.scope }
    local pfx = "addon." .. def.id .. "."

    local menus     = {}   -- container objects the addon created
    local conns     = {}   -- tracked signal connections
    local keyIds    = {}   -- keybind ids to clear (feature master keys + ctx keybinds)
    local unloadCbs = {}

    -- per-addon persistence, namespaced so two addons can't clash (per-game store)
    ctx.persist = {
        get = function(k, d) return persist.get(pfx .. k, d) end,
        set = function(k, v) persist.set(pfx .. k, v) end,
    }
    function ctx:notify(msg, dur) pcall(notify.info, "[" .. def.name .. "] " .. tostring(msg), dur or 4) end
    function ctx:log(msg) log.info("[addon:" .. def.id .. "] " .. tostring(msg)) end

    -- Connect a signal and have it auto-disconnected on teardown.
    function ctx:connect(signal, fn)
        local ok, c = pcall(function() return signal:Connect(fn) end)
        if ok and c then conns[#conns + 1] = c; return c end
        return nil
    end
    function ctx:onUnload(fn) if type(fn) == "function" then unloadCbs[#unloadCbs + 1] = fn end end

    -- A menu = a navigator container this addon owns. Items wrap feature/components.
    function ctx:menu(title)
        local box = container.new(window.parent(), title or def.name)
        menus[#menus + 1] = box
        local menu = { container = box }

        -- Full feature row (toggle + optional settings array: sliders / keybinds /
        -- buttons / dropdowns inside its cog panel). The power API.
        function menu:feature(fdef)
            fdef = fdef or {}
            fdef.id = fdef.id or (pfx .. persist.slug(fdef.name or "feature"))
            keyIds[#keyIds + 1] = fdef.id   -- so unload clears its master keybind
            local h = feature.declare(fdef)
            box:add(h.root)
            return h
        end
        function menu:toggle(name, opts, cb)
            opts = opts or {}
            return self:feature({
                name = name, description = opts.description,
                default = opts.default, onToggle = cb,
                defaultKey = toKeyCode(opts.key),
                settings = opts.settings,
            })
        end
        function menu:button(name, cb)
            local f = components.Button(box.features, { text = name, onClick = cb })
            box:add(f); return f
        end
        function menu:label(text)   local f = components.Label(box.features, text);   box:add(f); return f end
        function menu:section(text) local f = components.Section(box.features, text); box:add(f); return f end
        function menu:slider(name, opts, cb)
            opts = opts or {}
            local skey = persist.slug(name)
            local h = components.Slider(box.features, {
                text = name, min = opts.min, max = opts.max, step = opts.step,
                default = ctx.persist.get(skey, opts.default),
                onChange = function(v) ctx.persist.set(skey, v); if cb then cb(v) end end,
            })
            box:add(h.frame); return h
        end
        function menu:dropdown(name, opts, cb)
            opts = opts or {}
            local skey = persist.slug(name)
            local h = components.Dropdown(box.features, {
                label = name, options = opts.options,
                default = ctx.persist.get(skey, opts.default),
                onChange = function(v) ctx.persist.set(skey, v); if cb then cb(v) end end,
            })
            box:add(h.frame); return h
        end
        function menu:textbox(name, opts, cb)
            opts = opts or {}
            local skey = persist.slug(name)
            local h = components.TextBox(box.features, {
                label = name, placeholder = opts.placeholder,
                default = ctx.persist.get(skey, opts.default),
                onChange = function(v) ctx.persist.set(skey, v); if cb then cb(v) end end,
            })
            box:add(h.frame); return h
        end
        function menu:keybind(name, opts, onPress, onRelease)
            opts = opts or {}
            local kid   = pfx .. "key." .. persist.slug(name)
            keyIds[#keyIds + 1] = kid
            local saved = persist.stringToKey(persist.get(kid .. ".bind"))
            local eff   = saved or toKeyCode(opts.default)
            if eff and eff ~= Enum.KeyCode.Unknown then keybinds.set(kid, eff, onPress, onRelease) end
            local h = components.KeybindSetter(box.features, {
                label = name, default = eff,
                onChange = function(k)
                    keybinds.set(kid, k, onPress, onRelease)
                    persist.set(kid .. ".bind", persist.keyToString(k))
                end,
            })
            box:add(h.frame); return h
        end
        return menu
    end

    -- Full teardown: run unload callbacks, drop connections, clear keybinds,
    -- destroy menus. Safe to call once; the manager calls it on disable/reload/exit.
    function ctx._destroy()
        for _, fn in ipairs(unloadCbs) do pcall(fn) end
        for _, c in ipairs(conns)     do pcall(function() c:Disconnect() end) end
        for _, id in ipairs(keyIds)   do pcall(function() keybinds.clear(id) end) end
        for _, box in ipairs(menus)   do pcall(function() box:destroy() end) end
        menus, conns, keyIds, unloadCbs = {}, {}, {}, {}
    end

    return ctx
end

-- ===== the global `Pantheon` table handed to every addon =====
API.Pantheon = {
    register = function(def)
        if type(def) ~= "table" then
            log.warn("[addons] Pantheon.register expects a table"); return
        end
        if type(def.setup) ~= "function" then
            log.warn("[addons] addon '" .. tostring(def.name) .. "' has no setup(ctx) function")
        end
        def.file = currentFile
        registered[#registered + 1] = def
        return def
    end,

    -- raw building blocks for power users (the high-level ctx:menu API covers most)
    feature    = feature,
    components = components,
    container  = container,
    window     = window,
    notify     = notify,
    keybinds   = keybinds,
    persist    = persist,
    log        = log,
    getService = function(n) return game:GetService(n) end,
}

return API
end

_MODULES["modules.addons.init"] = function()
-- Addons: drop-in user/community scripts that extend Pantheon WITHOUT editing its
-- code -- the same spirit as Infinite Yield's addons.
--
-- An addon is a .lua file in the executor's `Pantheon/addons` folder. On boot we
-- run each enabled file with a global `Pantheon` API (see modules/addons/api.lua);
-- the file calls `Pantheon.register{ name, scope, setup }`. An addon's setup() runs
-- only when it's ENABLED (toggle in this menu) AND its `scope` matches the current
-- game -- so a game-specific addon's feature menu "just shows up" in that game and
-- stays out of every other one, no code edits needed.
--
-- This "Addons" panel is the manager: install an addon from a URL, toggle each one
-- on/off (which builds or tears down its menus), reload the folder, or delete one.
-- Each enabled+matching addon gets its OWN navigator menu (built by its setup()).

local window     = require("ui.window")
local container  = require("ui.container")
local components = require("ui.components")
local notify     = require("ui.notify")
local persist    = require("core.persist")
local log        = require("core.log")
local env        = require("core.env")
local theme      = require("ui.theme")
local registry   = require("games.registry")
local api        = require("modules.addons.api")

local module = {}

local FOLDER       = "Pantheon/addons"
local ENABLED_KEY  = "addons.enabled"   -- cross-game (global) map { [fileId] = bool }

-- fileId -> { id, file, path, defs = { def, ... }, ctxs = { ctx, ... }, active, err }
local entries   = {}
local box                       -- the "Addons" manager container
local listFrame                 -- holder the installed-addon rows rebuild into
local rebuildList               -- forward decl (manager row builder)

-- ---- helpers ----

local function fsReady()
    return env.listfiles and env.readfile and env.isfile and env.writefile and env.makefolder
end

local function ensureFolder()
    if not env.makefolder or not env.isfolder then return end
    if not env.isfolder("Pantheon")      then pcall(env.makefolder, "Pantheon")      end
    if not env.isfolder(FOLDER)          then pcall(env.makefolder, FOLDER)          end
end

-- basename of a path, minus the .lua extension. listfiles returns "/"- or "\\"-
-- separated paths depending on the executor; handle both.
local function fileIdOf(path)
    return tostring(path):match("([^/\\]+)%.lua$")
end

local function enabledMap() return persist.getGlobal(ENABLED_KEY, {}) or {} end
local function isEnabled(id)
    local v = enabledMap()[id]
    if v == nil then return true end   -- a freshly-installed addon defaults ON
    return v and true or false
end
local function setEnabledFlag(id, v)
    local m = enabledMap()
    m[id] = v and true or false
    persist.setGlobal(ENABLED_KEY, m)
end

-- Does an addon's scope apply to the current game? Mirrors games.registry /
-- tech engine scope semantics: nil/"universal" always; a PlaceId/GameId number
-- (or a list of them); or "char:<name>" via the game module's detectCharacter().
local function scopeMatches(scope)
    if scope == nil or scope == "universal" then return true end
    if scope == game.PlaceId or scope == game.GameId then return true end
    if type(scope) == "table" then
        for _, s in ipairs(scope) do
            if s == game.PlaceId or s == game.GameId then return true end
        end
        return false
    end
    if type(scope) == "string" then
        local want = scope:match("^char:(.+)$")
        if want then
            local mod = registry.current()
            local fn  = mod and mod.detectCharacter
            if type(fn) == "function" then
                local ok, name = pcall(fn)
                return (ok and name == want) or false
            end
        end
    end
    return false
end

local function scopeLabel(scope)
    if scope == nil or scope == "universal" then return "universal" end
    if scopeMatches(scope) then return "this game" end
    return "other game"
end

-- ---- load / activate ----

-- Run an addon FILE's chunk (which calls Pantheon.register). Returns the list of
-- defs it registered, each tagged with the file's id + path. Errors are captured.
local function loadFile(id, path)
    local ok, src = pcall(env.readfile, path)
    if not ok or not src then return nil, "read failed" end
    local chunk, cerr = loadstring(src, "=[PantheonAddon:" .. id .. "]")
    if not chunk then return nil, "compile: " .. tostring(cerr) end
    -- Inject the Pantheon global into the chunk's environment (and pass it as a
    -- vararg too, so `local Pantheon = ...` works as well as the global).
    local fenv = setmetatable({ Pantheon = api.Pantheon }, { __index = getfenv() })
    pcall(setfenv, chunk, fenv)
    api.setCurrentFile(id)
    local rok, rerr = pcall(chunk, api.Pantheon)
    api.setCurrentFile(nil)
    if not rok then return nil, "run: " .. tostring(rerr) end
    local defs = api.takeRegistered()
    for i, d in ipairs(defs) do
        d.id   = (#defs == 1) and id or (id .. "#" .. i)
        d.file = id
        d.path = path
    end
    return defs
end

-- Build the ctx + run setup() for every def in an entry whose scope matches now.
local function activate(entry)
    if entry.active then return end
    entry.ctxs = {}
    for _, def in ipairs(entry.defs or {}) do
        if type(def.setup) == "function" and scopeMatches(def.scope) then
            local ctx = api.makeContext(def)
            local ok, err = pcall(def.setup, ctx)
            if not ok then
                log.warn("[addons] '" .. tostring(def.name) .. "' setup error: " .. tostring(err))
                pcall(ctx._destroy)
            else
                entry.ctxs[#entry.ctxs + 1] = ctx
            end
        end
    end
    entry.active = true
end

local function deactivate(entry)
    for _, ctx in ipairs(entry.ctxs or {}) do pcall(ctx._destroy) end
    entry.ctxs   = {}
    entry.active = false
end

-- Load (chunk-run) an enabled file and activate its matching defs. No-op if the
-- file is disabled (we keep a bare entry so the manager still lists it).
local function loadEntry(id, path)
    local entry = entries[id] or { id = id, path = path, defs = {}, ctxs = {} }
    entry.path = path
    entries[id] = entry
    if not isEnabled(id) then entry.defs = {}; entry.err = nil; return entry end
    local defs, err = loadFile(id, path)
    if not defs then
        entry.defs = {}; entry.err = err
        log.warn("[addons] failed to load '" .. id .. "': " .. tostring(err))
        return entry
    end
    entry.defs = defs; entry.err = nil
    activate(entry)
    return entry
end

-- Discover every .lua in the addons folder and load the enabled ones.
local function discover()
    if not fsReady() then return end
    ensureFolder()
    local ok, files = pcall(env.listfiles, FOLDER)
    if not ok or type(files) ~= "table" then return end
    for _, path in ipairs(files) do
        local id = fileIdOf(path)
        if id then loadEntry(id, path) end
    end
end

-- ---- runtime ops (toggle / reload / install / delete) ----

local function refreshUI()
    if rebuildList then rebuildList() end
    container.refreshNavigator()
end

local function toggleAddon(id, on)
    setEnabledFlag(id, on)
    local entry = entries[id]
    if not entry then refreshUI(); return end
    if on then
        loadEntry(id, entry.path)        -- (re)load chunk + activate
    else
        deactivate(entry)
        entry.defs = {}                  -- forget defs; a re-enable re-runs the chunk
    end
    refreshUI()
end

local function reloadAll()
    for _, entry in pairs(entries) do deactivate(entry) end
    entries = {}
    discover()
    refreshUI()
    pcall(notify.info, "Addons reloaded", 3)
end

-- sanitize a desired filename to a safe, extensionless id
local function safeName(name)
    name = tostring(name or ""):gsub("%.lua$", "")
    name = name:gsub("[^%w%-_ ]", ""):gsub("%s+", "_")
    if name == "" then name = "addon_" .. tostring(#(entries) + 1) end
    return name
end

local function installFromUrl(url, name)
    if not fsReady() then pcall(notify.warn, "Filesystem APIs unavailable in this executor"); return end
    url = tostring(url or "")
    if url == "" then pcall(notify.warn, "Paste an addon URL first"); return end
    -- derive a name from the URL if none was typed
    if not name or name == "" then name = fileIdOf(url) or url:match("([^/]+)$") or "addon" end
    local id   = safeName(name)
    local okF, src = pcall(env.HttpGet, url)
    if not okF or not src or #src == 0 then pcall(notify.warn, "Download failed"); return end
    ensureFolder()
    local path = FOLDER .. "/" .. id .. ".lua"
    local okW = pcall(env.writefile, path, src)
    if not okW then pcall(notify.warn, "Could not write addon file"); return end
    setEnabledFlag(id, true)
    loadEntry(id, path)
    refreshUI()
    pcall(notify.success, "Installed addon: " .. id, 4)
end

local function deleteAddon(id)
    local entry = entries[id]
    if entry then deactivate(entry) end
    if entry and entry.path and env.delfile then pcall(env.delfile, entry.path) end
    entries[id] = nil
    local m = enabledMap(); m[id] = nil; persist.setGlobal(ENABLED_KEY, m)
    refreshUI()
end

-- ---- manager UI ----

local function buildRow(parent, entry)
    local id   = entry.id
    local def  = (entry.defs and entry.defs[1]) or nil
    local name = (def and def.name) or id
    local on   = isEnabled(id)

    local f = Instance.new("Frame")
    f.Size = UDim2.new(1, 0, 0, 26)
    f.BackgroundColor3 = theme.bgAlt
    f.BorderSizePixel = 0
    f.Parent = parent

    local nameLbl = Instance.new("TextLabel")
    nameLbl.Size = UDim2.new(1, -150, 1, 0)
    nameLbl.Position = UDim2.fromOffset(8, 0)
    nameLbl.BackgroundTransparency = 1
    nameLbl.Text = entry.err and (name .. "  (error)") or name
    nameLbl.TextColor3 = on and theme.fg or theme.fgDim
    nameLbl.Font = theme.font; nameLbl.TextSize = 12
    nameLbl.TextXAlignment = Enum.TextXAlignment.Left
    nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
    nameLbl.Parent = f

    -- scope tag (greyed when the addon isn't applicable to this game)
    local tag = Instance.new("TextLabel")
    tag.Size = UDim2.fromOffset(72, 16); tag.Position = UDim2.new(1, -120, 0.5, -8)
    tag.BackgroundTransparency = 1
    tag.Text = def and scopeLabel(def.scope) or (entry.err and "load failed" or (on and "" or "disabled"))
    tag.TextColor3 = theme.fgDim; tag.Font = theme.font; tag.TextSize = 10
    tag.TextXAlignment = Enum.TextXAlignment.Right
    tag.Parent = f

    local toggle = Instance.new("TextButton")
    toggle.Size = UDim2.fromOffset(38, 18); toggle.Position = UDim2.new(1, -44, 0.5, -9)
    toggle.AutoButtonColor = false
    toggle.BackgroundColor3 = on and theme.on or theme.off
    toggle.TextColor3 = theme.fg; toggle.Font = theme.fontBold; toggle.TextSize = 10
    toggle.Text = on and "ON" or "OFF"
    toggle.Parent = f
    toggle.MouseButton1Click:Connect(function() toggleAddon(id, not isEnabled(id)) end)

    local del = Instance.new("TextButton")
    del.Size = UDim2.fromOffset(18, 18); del.Position = UDim2.new(1, -64, 0.5, -9)
    del.BackgroundColor3 = theme.danger; del.AutoButtonColor = false
    del.TextColor3 = theme.fg; del.Font = theme.fontBold; del.TextSize = 10
    del.Text = "X"
    del.Parent = f
    del.MouseButton1Click:Connect(function() deleteAddon(id) end)

    return f
end

function module.register()
    box = container.new(window.parent(), "Addons")

    local holder = Instance.new("Frame")
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.BackgroundTransparency = 1
    local hl = Instance.new("UIListLayout", holder)
    hl.SortOrder = Enum.SortOrder.LayoutOrder
    hl.Padding = UDim.new(0, 2)

    local ord = 0
    local function place(inst) ord = ord + 1; inst.LayoutOrder = ord; inst.Parent = holder; return inst end

    if not fsReady() then
        place(components.Label(holder, "Filesystem APIs unavailable -- addons need an executor with listfiles/readfile."))
    else
        place(components.Section(holder, "Install"))
        local urlBox  = components.TextBox(holder, { label = "URL", placeholder = "raw .lua URL" })
        place(urlBox.frame)
        local nameBox = components.TextBox(holder, { label = "Name", placeholder = "optional file name" })
        place(nameBox.frame)
        place(components.Button(holder, { text = "Install from URL", onClick = function()
            installFromUrl(urlBox:Get(), nameBox:Get())
            urlBox:Set(""); nameBox:Set("")
        end }))
        place(components.Button(holder, { text = "Reload addons", onClick = reloadAll }))
        place(components.Label(holder, "Drop .lua files in:  " .. FOLDER))
        place(components.Section(holder, "Installed"))
    end

    listFrame = Instance.new("Frame")
    listFrame.Size = UDim2.new(1, 0, 0, 0)
    listFrame.AutomaticSize = Enum.AutomaticSize.Y
    listFrame.BackgroundTransparency = 1
    listFrame.Parent = holder
    listFrame.LayoutOrder = 999
    local ll = Instance.new("UIListLayout", listFrame)
    ll.SortOrder = Enum.SortOrder.LayoutOrder
    ll.Padding = UDim.new(0, 1)

    rebuildList = function()
        for _, c in ipairs(listFrame:GetChildren()) do
            if not c:IsA("UIListLayout") then c:Destroy() end
        end
        local ids = {}
        for id in pairs(entries) do ids[#ids + 1] = id end
        table.sort(ids)
        local n = 0
        for _, id in ipairs(ids) do
            local r = buildRow(listFrame, entries[id]); n = n + 1; r.LayoutOrder = n
        end
        if n == 0 then
            local empty = components.Label(listFrame, "No addons installed.")
            empty.LayoutOrder = 1
        end
    end

    box:add(holder)

    -- discover + load + activate BEFORE init.lua calls nav.populate() so every
    -- addon's menu (and this manager) is listed in the navigator from boot.
    discover()
    rebuildList()

    local count = 0
    for _ in pairs(entries) do count = count + 1 end
    log.info("Addons registered (" .. count .. " found)")
end

function module.destroy()
    -- Tear down every active addon (disconnect its connections + clear keybinds +
    -- destroy its menus) so a re-execute doesn't leak them. The manager container
    -- itself is destroyed by window.destroy() with the rest of the GUI.
    for _, entry in pairs(entries) do pcall(deactivate, entry) end
    entries     = {}
    box         = nil
    listFrame   = nil
    rebuildList = nil
end

return module
end

_MODULES["games.jjs"] = function()
-- Jujutsu Shenanigans (PlaceId 17016840407) integration.
--
-- Registered into the game registry; its container only appears when you're
-- actually in JJS -- init.lua calls registry.current().register() gated on
-- game.PlaceId, so this never shows in other games.
--
-- Feature: Nanami "Perfect Special" -- auto-times Salaryman's R special, Ratio
-- Point (NanamiService.RE.RightActivated). Per the JJS wiki, Ratio Point marks a
-- target within 70 STUDS and runs a quick-time event whose timing speeds up as
-- the target's HP drops; this fires the confirm after an HP-scaled delay so it
-- lands on the ratio. Ported from the old lock-on script, which used a wrong
-- 27-stud range -- corrected to the wiki's 70.

local registry   = require("games.registry")
local window     = require("ui.window")
local container  = require("ui.container")
local feature    = require("ui.feature")
local components = require("ui.components")
local keybinds   = require("core.keybinds")
local persist    = require("core.persist")
local state      = require("modules.aim.state")
local targeting  = require("modules.aim.targeting")
local shiftlock  = require("modules.aim.shiftlock")
local log        = require("core.log")
local notify     = require("ui.notify")

local Players             = game:GetService("Players")
local ReplicatedStorage   = game:GetService("ReplicatedStorage")
local RunService          = game:GetService("RunService")
local VirtualInputManager = game:GetService("VirtualInputManager")

-- JJS spans multiple places (17016840407 = "Lobby", 9391468976 = experience root)
-- under ONE GameId 3508322461 (grabbed in-game; matches the legacy script's id).
-- registry.current() checks game.GameId, so the GameId entry covers EVERY place /
-- VIP server in one go; the place ids are just extra redundancy.
local JJS_IDS = { 3508322461, 17016840407, 9391468976 }   -- GameId first, then known places

local JJS = {}

local CFG = {
    range    = 70,     -- studs -- wiki: Ratio Point marks a target within 70 studs
    delayHi  = 0.63,   -- s, target >= 80% HP (QTE slower early-fight)
    delayLo  = 0.55,   -- s, target <  80% HP (QTE faster as HP drops)
    hpThresh = 80,     -- % HP threshold between the two timings
}
local enabled = false
local emoteList            -- the ScrollingFrame the emote keybind rows live in
local emoteKeyIds = {}     -- bound keybind ids for the emotes (cleared on rescan / destroy)
local emoteConns = {}      -- watchers that auto-rescan when the emote GUI loads/changes

local function rootOf(c) return c and c:FindFirstChild("HumanoidRootPart") end

-- Prefer the Target Select / Lock-On target; fall back to the nearest valid
-- target so it still works if you haven't engaged Target Select first.
local function targetChar()
    local t = state.target
    if t then
        return (state.target_type == "npc") and t or t.Character
    end
    -- Fallback: nearest valid target when Target Select hasn't engaged. Mirror the
    -- (target, type) handling above -- with Bot Mode on, best may be an NPC Model,
    -- and reading `.Character` off a Model throws ("not a valid member").
    local best, ty = targeting.getBestTarget()
    if not best then return nil end
    return (ty == "npc") and best or best.Character
end

local function ratioPointPerfect()
    if not enabled then return end
    local tChar = targetChar()
    if not tChar then return end
    local myRoot, tRoot = rootOf(Players.LocalPlayer.Character), rootOf(tChar)
    if not (myRoot and tRoot) then return end
    if (myRoot.Position - tRoot.Position).Magnitude > CFG.range then return end
    local hum = tChar:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local hpPct = (hum.Health / math.max(hum.MaxHealth, 1)) * 100
    local delay = (hpPct < CFG.hpThresh) and CFG.delayLo or CFG.delayHi
    task.delay(delay, function()
        pcall(function()
            ReplicatedStorage.Knit.Knit.Services.NanamiService.RE.RightActivated:FireServer(tChar)
        end)
    end)
end

-- Per-game move scanner hook (called by modules.tech.scanner first; generic scan is
-- the fallback). JJS's hotbar: PlayerGui.Controls (SG) > Controls > Moveset > <MoveName>
-- > ItemName -- the inner "Controls" Frame matters (the SG and its Frame child share a
-- name). Each ItemName TextButton has the real MouseButton1Down handler on it directly
-- (no inner Base button like TSB). Slot frame's Name is the move name (e.g. "Projection
-- Breaker"); keys 1..N map to the slots LEFT-TO-RIGHT by AbsolutePosition.X. The scanner
-- annotates `move` (Knit service name) from these entries via the shared stem matcher.
local lastScanReport = -1
local function scanReport(stage, n, names)
    if n == lastScanReport then return end
    lastScanReport = n
    local msg = ("JJS scanMoves [%s]: %d move(s) %s"):format(stage, n, names and ("[" .. names .. "]") or "")
    log.info(msg)
    pcall(function() notify.info(msg, 6) end)
end

-- JJS hotbar lives at PlayerGui.Main.Controls.Moveset.<MoveName>.ItemName. There's
-- a SEPARATE ScreenGui named "Controls" in PlayerGui that's the Mobile UI (no
-- Moveset descendant) -- earlier versions of this hook targeted the wrong SG.
function JJS.scanMoves(pg)
    local main = pg:FindFirstChild("Main")
    if not main then scanReport("no Main SG", 0); return nil end
    local controls = main:FindFirstChild("Controls")
    local moveset  = controls and controls:FindFirstChild("Moveset")
    if not moveset then scanReport("no Main.Controls.Moveset", 0); return nil end

    local slots = {}
    for _, child in ipairs(moveset:GetChildren()) do
        local btn = child:FindFirstChild("ItemName")
        if btn and (btn:IsA("TextButton") or btn:IsA("ImageButton")) then
            -- Read the slot's actual keybind from the Key.Key TextLabel (per
            -- reference_jjs_autoblock: JJS stores "1".."4" there). Position-
            -- index fallback if the label is missing; the previous assume-
            -- positional-order code would send the wrong slot key whenever
            -- slots weren't packed left-to-right starting at "1".
            local keyFrame = child:FindFirstChild("Key")
            local keyTxt = keyFrame and keyFrame:FindFirstChild("Key")
            local label = keyTxt and keyTxt:IsA("TextLabel") and keyTxt.Text
            slots[#slots + 1] = {
                name = child.Name, button = btn,
                x = btn.AbsolutePosition.X,
                key = (label and label ~= "" and label) or nil,
            }
        end
    end
    if #slots == 0 then scanReport("Moveset empty", 0); return nil end
    table.sort(slots, function(a, b) return a.x < b.x end)

    -- Engine's Use Move path = fireButton (firesignal MouseButton1Down) on the
    -- ItemName TextButton. Confirmed live by a throwaway tester: PB casts when
    -- MB1Down is fired on PlayerGui.Main.Controls.Moveset["Projection Breaker"]
    -- .ItemName -- the earlier "ItemName is visual-only" guess was wrong, the
    -- button's MB1Down handler IS the move's fire-on-press. We still record
    -- `key` so JJS.useMove (RE-direct path) can use it if needed; useKey is
    -- omitted so engine takes the button-fire path by default.
    local out, names = {}, {}
    for i, s in ipairs(slots) do
        out[#out + 1] = {
            button = s.button, name = s.name, text = s.name,
            key = s.key or tostring(i),
        }
        names[#names + 1] = s.name
    end
    scanReport("ok", #out, table.concat(names, ", "))
    return out
end

-- Per-game useMove hook. We're now relying on the engine's button-fire path
-- (firesignal MouseButton1Down on the slot's ItemName button -- confirmed
-- working live for Projection Breaker), so this hook only fires when a move
-- is EXPLICITLY pinned to a Knit RE remote below. No substring/auto guesses
-- -- those risked firing the wrong move on a coincidental name match.
-- Add an entry here when (a) the button-fire path doesn't work for a move,
-- AND (b) we've verified the exact service + remote + arg shape.
local MOVE_REMOTE = {
    -- ["Move Name"] = { service = "FooService", remote = "Activated" },
}

local function findKnitRE(svcName, remoteName)
    local knit = ReplicatedStorage:FindFirstChild("Knit")
    if not knit then return nil end
    local inner = knit:FindFirstChild("Knit") or knit
    local svcs = inner:FindFirstChild("Services")
    local svc = svcs and svcs:FindFirstChild(svcName)
    local re = svc and svc:FindFirstChild("RE")
    return re and re:FindFirstChild(remoteName) or nil
end

-- Detect which JJS character we're playing as, for char-locked techs. The
-- HUD's Ultimate.Title text is the awakening name and is character-unique
-- (verified via reference_jjs_autoblock: "HUD swap signal = ultimate Title;
-- stable thru variant switches"). Returns the name or nil if not yet built.
function JJS.detectCharacter()
    local pg = Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
    if not pg then return nil end
    local main = pg:FindFirstChild("Main")
    local controls = main and main:FindFirstChild("Controls")
    local ult = controls and controls:FindFirstChild("Ultimate")
    local title = ult and ult:FindFirstChild("Title")
    if title and title:IsA("TextLabel") then
        local t = title.Text
        if t and t ~= "" then return t end
    end
    return nil
end

function JJS.useMove(name)
    local pin = MOVE_REMOTE[name]
    if not pin then return false end
    local re = findKnitRE(pin.service, pin.remote)
    if not re then
        log.warn(("[jjs] useMove: %s.RE.%s not found, falling through"):format(pin.service, pin.remote))
        return false
    end
    local ok, err = pcall(function() re:FireServer() end)
    if not ok then
        log.warn(("[jjs] useMove fire %s: %s"):format(pin.service, tostring(err)))
        return false
    end
    return true
end

-- ===== Emote Keybinds =====
-- JJS emote menu: PlayerGui.Emotes.Emote.Page<N>.<slot>.Clickable (the button) +
-- .EmoteName.Txt (the emote's name). Bind a key to fire an emote's Clickable
-- without opening the menu.

-- fire a GUI button by the signal it actually has handlers on (firesignal), with a
-- real VIM click as a last resort.
local function fireGui(btn)
    if not btn then return end
    local function conns(sig)
        if typeof(getconnections) ~= "function" then return nil end
        local ok, c = pcall(getconnections, sig); return ok and c or nil
    end
    if typeof(firesignal) == "function" then
        local cx = btn.AbsolutePosition.X + btn.AbsoluteSize.X / 2
        local cy = btn.AbsolutePosition.Y + btn.AbsoluteSize.Y / 2
        local d = conns(btn.MouseButton1Down)
        if d and #d > 0 then
            pcall(firesignal, btn.MouseButton1Down, cx, cy)
            local u = conns(btn.MouseButton1Up); if u and #u > 0 then pcall(firesignal, btn.MouseButton1Up, cx, cy) end
            return
        end
        local c = conns(btn.MouseButton1Click); if c and #c > 0 then pcall(firesignal, btn.MouseButton1Click); return end
        local a = conns(btn.Activated);          if a and #a > 0 then pcall(firesignal, btn.Activated); return end
    end
    local VIM = game:GetService("VirtualInputManager")
    local p, s = btn.AbsolutePosition, btn.AbsoluteSize
    local x, y = p.X + s.X / 2, p.Y + s.Y / 2 + 36
    pcall(function() VIM:SendMouseButtonEvent(x, y, 0, true, game, 0); task.wait(); VIM:SendMouseButtonEvent(x, y, 0, false, game, 0) end)
end

-- Buy Cola: the Soda purchase button in the shop. Resolved fresh each click so it
-- survives the shop UI rebuilding. Path: PlayerGui.Menus.Group.Shop.Items.Shop.Shop.Soda.Purchase.Cash
local COLA_PATH = { "Menus", "Group", "Shop", "Items", "Shop", "Shop", "Soda", "Purchase", "Cash" }
local function findCola()
    local node = Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
    for _, n in ipairs(COLA_PATH) do
        if not node then return nil end
        node = node:FindFirstChild(n)
    end
    return node
end
local function buyCola()
    local b = findCola()
    if b then fireGui(b); pcall(notify.info, "Bought cola", 2)
    else pcall(notify.warn, "Soda purchase button not found -- open the shop once?") end
end

-- re-resolve a slot's Clickable at fire time (survives the menu rebuilding)
local function findClickable(page, slot)
    local pg = Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
    local emote = pg and pg:FindFirstChild("Emotes")
    emote = emote and emote:FindFirstChild("Emote")
    local p = emote and emote:FindFirstChild(page)
    if not p then return nil end
    local s = p:FindFirstChild(slot)
    if s then local c = s:FindFirstChild("Clickable"); if c then return c end end
    -- fallback: any Clickable under the page whose parent matches the slot name
    for _, d in ipairs(p:GetDescendants()) do
        if d.Name == "Clickable" and d.Parent and d.Parent.Name == slot then return d end
    end
    return nil
end

-- list { name, page, slot } for every emote slot that has a Clickable. Lenient:
-- any descendant named "Clickable" counts as a slot; the name is read from a
-- sibling EmoteName.Txt if present, else falls back to page+slot. Returns a diag
-- table too so we can surface WHERE detection fails.
local function scanEmotes()
    local pg = Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
    local emotes = pg and pg:FindFirstChild("Emotes")
    local emote = emotes and emotes:FindFirstChild("Emote")
    local out, diag = {}, { emotes = emotes ~= nil, emote = emote ~= nil, pages = 0, slots = 0 }
    if not emote then return out, diag end
    -- find every "Clickable" under a Page* and treat its parent as the slot
    for _, page in ipairs(emote:GetChildren()) do
        if page.Name:sub(1, 4) == "Page" then
            diag.pages = diag.pages + 1
            for _, desc in ipairs(page:GetDescendants()) do
                if desc.Name == "Clickable" then
                    local slot = desc.Parent
                    diag.slots = diag.slots + 1
                    local nm
                    local en  = slot and slot:FindFirstChild("EmoteName")
                    local txt = en and (en:FindFirstChild("Txt") or en)
                    if txt then local ok, t = pcall(function() return txt.Text end); if ok and type(t) == "string" and t ~= "" then nm = t end end
                    out[#out + 1] = {
                        name = nm or (page.Name .. " " .. (slot and slot.Name or "?")),
                        page = page.Name, slot = slot and slot.Name or "?",
                    }
                end
            end
        end
    end
    return out, diag
end

local function rebuildEmotes()
    if not emoteList then return end
    for _, id in ipairs(emoteKeyIds) do pcall(function() keybinds.clear(id) end) end
    emoteKeyIds = {}
    for _, c in ipairs(emoteList:GetChildren()) do if not c:IsA("UIListLayout") then c:Destroy() end end

    local emotes, diag = scanEmotes()
    if #emotes == 0 then
        local msg
        if not diag.emotes then msg = "PlayerGui.Emotes missing"
        elseif not diag.emote then msg = "Emotes.Emote missing"
        elseif diag.pages == 0 then msg = "no Page* (open the emote menu?)"
        elseif diag.slots == 0 then msg = "pages found, 0 Clickables"
        else msg = "none" end
        local empty = components.Label(emoteList, "Emotes: " .. msg .. "  -> Rescan")
        empty.LayoutOrder = 1
        return
    end
    for i, e in ipairs(emotes) do
        local id = "jjs.emote." .. persist.slug(e.name)
        local function onPress() local btn = findClickable(e.page, e.slot); if btn then fireGui(btn) end end
        local saved = persist.stringToKey(persist.get(id .. ".bind"))
        if saved and saved ~= Enum.KeyCode.Unknown then keybinds.set(id, saved, onPress); emoteKeyIds[#emoteKeyIds + 1] = id end
        local ks = components.KeybindSetter(emoteList, {
            label   = e.name,
            default = saved,
            onChange = function(k)
                if k and k ~= Enum.KeyCode.Unknown then
                    keybinds.set(id, k, onPress)
                    if not table.find(emoteKeyIds, id) then emoteKeyIds[#emoteKeyIds + 1] = id end
                else
                    keybinds.clear(id)
                end
                persist.set(id .. ".bind", persist.keyToString(k))
            end,
        })
        ks.frame.LayoutOrder = i
    end
end

-- ===== Auto QTE (Higuruma "Deadly Sentencing" struggle, and any JJS QTE) =====
-- No-misfire: reads the game's own prompt label PlayerGui.QTE (ScreenGui) ->
-- QTE_PC (TextLabel) and presses EXACTLY the W/A/S/D shown, ONLY while that QTE
-- GUI is active (Enabled + visible up its ancestry + single-letter text). QTE_PC
-- is used for nothing else, so it can't fire off the hotbar or other UI.
-- (GUI path confirmed by the [Dev] JJS QTE Dump inspector; Higuruma = HiromiService.)
--
-- Humanize (default on): instead of frame-perfect taps, wait a human reaction
-- time per new letter, sometimes "whiff" (a late press), and rarely hesitate for
-- ~1s once per QTE -- so it reads as a person barely scraping the win, not a bot.
local QTE_KEYS = { W = Enum.KeyCode.W, A = Enum.KeyCode.A, S = Enum.KeyCode.S, D = Enum.KeyCode.D }
local qte = {
    enabled  = false,
    humanize = true,
    reactMs  = 200,   -- reaction delay (ms) before reacting to the bar dropping
    jitterMs = 120,   -- random extra on top (ms)
    whiffPct = 12,    -- % chance to react late (a "whiff") when the bar dips
    pausePct = 10,    -- % chance of ONE longer hesitation per QTE (only while safely ahead)
    onlyWhenHit = false,  -- default: win EVERY QTE. On => only when you were hit (don't have the move)
    invert   = false,     -- flip bar direction if it turns out lower = winning
    conn = nil,
    -- runtime
    active = false, pushing = false, skip = false,
    targetLo = 0.53, targetHi = 0.62,   -- hover band (fraction of the bar that's yours)
    lastLetter = nil, lastPress = 0, reactReady = nil, pauseUntil = 0, pauseUsed = false,
}

local function qteReset()
    qte.active = false; qte.pushing = false; qte.skip = false
    qte.lastLetter = nil; qte.reactReady = nil; qte.pauseUntil = 0; qte.pauseUsed = false
end

-- Victim detection: if Final Judgement / Deadly Sentencing is in YOUR hotbar you
-- are the Higuruma player casting it; if it's NOT there and you got a QTE, you
-- were HIT with it. Reads the same Moveset the hotbar scanner uses.
local function localHasFinalJudgement()
    local pgui = Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
    local main = pgui and pgui:FindFirstChild("Main")
    local controls = main and main:FindFirstChild("Controls")
    local moveset = controls and controls:FindFirstChild("Moveset")
    if not moveset then return false end
    for _, child in ipairs(moveset:GetChildren()) do
        local n = child.Name:lower()
        if n:find("judgement") or n:find("judgment") or n:find("sentenc") then return true end
    end
    return false
end

-- Fresh per-QTE targets so each struggle looks a little different. The band is
-- kept just above 0.5 (even) so it "barely wins" instead of maxing the bar.
local function qteInitTargets()
    qte.targetLo = 0.52 + math.random() * 0.03   -- react when your fill dips to ~0.52-0.55
    qte.targetHi = 0.60 + math.random() * 0.06   -- ease off once ahead by ~0.60-0.66
    qte.pushing = false; qte.reactReady = nil
    qte.pauseUntil = 0; qte.pauseUsed = false
    -- decide once per QTE: skip if "only when hit" is on and we have the move
    -- equipped (i.e. we're the caster, not the victim).
    qte.skip = qte.onlyWhenHit and localHasFinalJudgement() or false
    qte.active = true
end

-- Your share of the struggle bar: Bar1 (yours) / Health width. >0.5 winning,
-- <0.5 losing. Path confirmed by the QTE dump: QTE.Health.Bar1.
local function qteFraction()
    local pgui = Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
    local scr  = pgui and pgui:FindFirstChild("QTE")
    if not scr then return nil end
    local health = scr:FindFirstChild("Health")
    local bar1   = health and health:FindFirstChild("Bar1")
    if not health or not bar1 then return nil end
    local total = health.AbsoluteSize.X
    if total <= 0 then return nil end
    return bar1.AbsoluteSize.X / total
end

-- Current required key for an ACTIVE QTE, or nil. Layered guards = misfire-proof.
local function qteCurrentKey()
    local pgui = Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
    if not pgui then return nil end
    local scr = pgui:FindFirstChild("QTE")
    if not scr then return nil end
    if scr:IsA("ScreenGui") and not scr.Enabled then return nil end
    local lbl = scr:FindFirstChild("QTE_PC")
    if not lbl or not (lbl:IsA("TextLabel") or lbl:IsA("TextButton")) then return nil end
    if not lbl.Visible then return nil end
    local n = lbl.Parent
    while n and n:IsA("GuiObject") do if not n.Visible then return nil end; n = n.Parent end
    local t = (tostring(lbl.Text):gsub("%s", "")):upper()
    if #t ~= 1 then return nil end
    return QTE_KEYS[t], t
end

local function qteTap(kc)
    VirtualInputManager:SendKeyEvent(true, kc, false, game)
    task.spawn(function() task.wait(0.012); VirtualInputManager:SendKeyEvent(false, kc, false, game) end)
end

local function qteReactionDelay()
    return (qte.reactMs + math.random() * qte.jitterMs) / 1000
end

local function qteStep()
    if not qte.enabled then return end
    local kc, letter = qteCurrentKey()
    if not kc then qteReset(); return end       -- no active QTE
    if not qte.active then qteInitTargets() end  -- new QTE just started
    if qte.skip then return end                  -- you're casting it, not being hit
    local now = os.clock()

    -- Base (fast) behaviour when Humanize is off: slam it to a quick win.
    if not qte.humanize then
        if letter ~= qte.lastLetter or (now - qte.lastPress) >= 0.05 then
            qteTap(kc); qte.lastLetter = letter; qte.lastPress = now
        end
        return
    end

    -- Humanized: keep your share of the bar hovering just above half so it
    -- barely wins instead of maxing out.
    local frac = qteFraction()

    -- Bar unreadable -> safe human mash so we never accidentally lose.
    if not frac then
        if letter ~= qte.lastLetter then
            qte.lastLetter = letter
            qte.reactReady = now + qteReactionDelay()
        elseif qte.reactReady and now >= qte.reactReady then
            qteTap(kc); qte.lastPress = now; qte.reactReady = now + 0.10 + math.random() * 0.10
        end
        return
    end

    if qte.invert then frac = 1 - frac end   -- flip if lower turns out to be winning

    -- serve out an active hesitation
    if now < qte.pauseUntil then return end

    if frac >= qte.targetHi then
        -- comfortably ahead: ease off, let the bar drift back toward the band.
        qte.pushing = false; qte.reactReady = nil
        -- take the single per-QTE hesitation now, while it's safe to.
        if (not qte.pauseUsed) and math.random(100) <= qte.pausePct then
            qte.pauseUsed = true
            qte.pauseUntil = now + 0.6 + math.random() * 0.7   -- ~0.6-1.3s
        end
        return
    end

    if frac <= qte.targetLo and not qte.pushing then
        -- bar dropped to the danger line: react like a human (sometimes late).
        qte.pushing = true
        local delay = qteReactionDelay()
        if math.random(100) <= qte.whiffPct then delay = delay + 0.12 + math.random() * 0.2 end
        qte.reactReady = now + delay
    end

    -- while pushing, mash the shown key at a human cadence until back above targetHi.
    if qte.pushing and qte.reactReady and now >= qte.reactReady then
        qteTap(kc)
        qte.lastPress = now
        qte.reactReady = now + 0.09 + math.random() * 0.08   -- ~90-170ms
    end
end

function JJS.register()
    -- LOUD load-time toast so we can SEE whether this code path actually ran in
    -- the executor. If you see "Pantheon loaded" but NOT "JJS registered" then
    -- registry.current() didn't find us for this PlaceId/GameId.
    local buildTag = tostring(rawget(_G, "PANTHEON_BUILD") or "?")
    pcall(function() notify.success("JJS registered (build " .. buildTag .. ")", 8) end)
    log.info("JJS module REGISTER on PlaceId=" .. tostring(game.PlaceId) .. " GameId=" .. tostring(game.GameId))

    -- Eagerly run scanMoves once now so the diagnostic toast fires at load
    -- (instead of waiting for the user to open the picker).
    pcall(function()
        local Players = game:GetService("Players")
        local pg = Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if pg then JJS.scanMoves(pg) end
    end)

    -- JJS ships its own shiftlock, which overlapped Pantheon's. Auto-engage PAIR mode
    -- so Pantheon syncs its shiftlock to the game's and keeps rotating in lockstep
    -- (instead of running a second competing one or fighting it). Per-game patch:
    -- runs at load, BEFORE any shiftlock-enable, so the foreign sweep never kills
    -- the game's shiftlock we want to pair with.
    shiftlock.setShiftlockMirror(true)

    local box = container.new(window.parent(), "Jujutsu Shenanigans")
    box:add(feature.declare({
        id          = "jjs.nanami_special",
        name        = "Nanami Perfect Special",
        description = "Auto-times Salaryman's R special, Ratio Point, onto your target. With a target within 70 studs (wiki range), pressing the key fires Ratio Point after an HP-timed delay so the confirm lands on the ratio QTE (the QTE speeds up at lower HP). Uses your Target Select / Lock-On target, else the nearest player.",
        default     = false,
        defaultKey  = Enum.KeyCode.R,
        onToggle    = function(v) enabled = v and true or false end,
        onKey       = function() ratioPointPerfect() end,
    }).root)

    -- Auto QTE: auto-clears the struggle QTE (Higuruma's Deadly Sentencing etc).
    box:add(feature.declare({
        id          = "jjs.auto_qte",
        name        = "Auto Final Judgement",
        description = "Auto-completes the struggle QTE (e.g. Higuruma's Deadly Sentencing). Reads the game's own prompt (PlayerGui.QTE.QTE_PC) and presses exactly the shown W/A/S/D key, only while that QTE is active -- it can't misfire onto the hotbar or anything else. Humanize (on by default) is bar-aware: it watches your side of the struggle bar (QTE.Health.Bar1) and only pushes when your fill dips toward half, easing off once you're ahead -- so it hovers just above 0.5 and BARELY wins instead of maxing the bar, with human reaction time, the odd late whiff, and a rare hesitation while safely ahead. Turn Humanize off to slam it to an instant win. Sliders tune reaction / whiff / hesitation; nudge them up if it wins too cleanly, down if it ever loses.",
        default     = false,
        onToggle    = function(v) qte.enabled = v and true or false; if not v then qteReset() end end,
        settings = {
            { type = "toggle", name = "Humanize (look human)", key = "humanize", default = true,
              onChange = function(v) qte.humanize = v and true or false end },
            { type = "toggle", name = "Only when hit (not casting)", key = "only_hit", default = false,
              onChange = function(v) qte.onlyWhenHit = v and true or false end },
            { type = "toggle", name = "Invert bar (if it acts backwards)", key = "invert", default = false,
              onChange = function(v) qte.invert = v and true or false end },
            { type = "slider", name = "Reaction time (ms)", key = "react_ms",
              min = 60, max = 500, step = 10, default = 200,
              onChange = function(v) qte.reactMs = v end },
            { type = "slider", name = "Reaction jitter (ms)", key = "jitter_ms",
              min = 0, max = 300, step = 10, default = 120,
              onChange = function(v) qte.jitterMs = v end },
            { type = "slider", name = "Whiff chance (%)", key = "whiff_pct",
              min = 0, max = 50, step = 1, default = 12,
              onChange = function(v) qte.whiffPct = v end },
            { type = "slider", name = "Hesitation chance (%)", key = "pause_pct",
              min = 0, max = 40, step = 1, default = 10,
              onChange = function(v) qte.pausePct = v end },
        },
    }).root)

    -- One Heartbeat drives the QTE reader; qteStep no-ops unless the feature's on.
    if qte.conn then pcall(function() qte.conn:Disconnect() end) end
    qte.conn = RunService.Heartbeat:Connect(qteStep)

    -- Buy Cola: feature row so it gets the cog (set a keybind there). The bound key
    -- buys; clicking the toggle also buys once then flips itself back off (momentary).
    local colaFeat
    colaFeat = feature.declare({
        id          = "jjs.buy_cola",
        name        = "Buy Cola",
        description = "Buys a soda from the shop (fires its Cash purchase button). Set a key in the cog to buy on press, or click the toggle to buy once.",
        default     = false,
        onKey       = function() buyCola() end,
        onToggle    = function(v) if v then buyCola(); task.defer(function() if colaFeat then colaFeat.setEnabled(false) end end) end end,
    })
    box:add(colaFeat.root)

    -- Emote Keybinds: bind a key to each emote (fires its Clickable without opening the menu)
    do
        local holder = Instance.new("Frame")
        holder.Size = UDim2.new(1, 0, 0, 0); holder.AutomaticSize = Enum.AutomaticSize.Y; holder.BackgroundTransparency = 1
        local hl = Instance.new("UIListLayout", holder); hl.SortOrder = Enum.SortOrder.LayoutOrder; hl.Padding = UDim.new(0, 2)
        local sec = components.Section(holder, "Emote Keybinds"); sec.LayoutOrder = 1
        local rescan = components.Button(holder, { text = "Rescan emotes", onClick = function() rebuildEmotes() end }); rescan.LayoutOrder = 2
        emoteList = Instance.new("ScrollingFrame")
        emoteList.Size = UDim2.new(1, 0, 0, 0); emoteList.AutomaticCanvasSize = Enum.AutomaticSize.Y
        emoteList.CanvasSize = UDim2.new(0, 0, 0, 0); emoteList.ScrollBarThickness = 4
        emoteList.BackgroundTransparency = 1; emoteList.BorderSizePixel = 0; emoteList.LayoutOrder = 3; emoteList.Parent = holder
        local el = Instance.new("UIListLayout", emoteList); el.SortOrder = Enum.SortOrder.LayoutOrder; el.Padding = UDim.new(0, 1)
        local MAXH = 200
        el:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            emoteList.Size = UDim2.new(1, 0, 0, math.min(el.AbsoluteContentSize.Y, MAXH))
        end)
        box:add(holder)
        rebuildEmotes()
        -- auto-rescan when the emote GUI loads/changes (it may not exist until the
        -- emote menu is opened the first time), debounced.
        local pg = Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if pg then
            local pending = false
            emoteConns[#emoteConns + 1] = pg.DescendantAdded:Connect(function(d)
                local n = d.Name
                if n == "Clickable" or n == "Emote" or n == "Emotes" then
                    if not pending then pending = true; task.delay(0.4, function() pending = false; rebuildEmotes() end) end
                end
            end)
        end
        -- a couple of deferred passes too, for emotes that populate shortly after join
        task.delay(2, function() pcall(rebuildEmotes) end)
        task.delay(5, function() pcall(rebuildEmotes) end)
    end

    log.info("JJS module registered -- Nanami Perfect Special + Buy Cola + Emote Keybinds")
end

-- Called by init.lua's shutdown (Auto Re-Execute / re-execute). register() runs
-- again on every boot, so anything it changed on shared modules must be undone
-- here or it compounds across teleports. The "Jujutsu Shenanigans" container,
-- the Nanami feature row, and its keybind are torn down by window.destroy /
-- keybinds.destroy; what's left is the module-level state below.
function JJS.destroy()
    enabled = false
    lastScanReport = -1
    -- stop the Auto QTE reader and clear its per-QTE state
    qte.enabled = false
    if qte.conn then pcall(function() qte.conn:Disconnect() end); qte.conn = nil end
    qteReset()
    -- clear emote keybinds (their ids are ours; the rows/keybind UI die with the window)
    for _, id in ipairs(emoteKeyIds) do pcall(function() keybinds.clear(id) end) end
    emoteKeyIds = {}
    for _, c in ipairs(emoteConns) do pcall(function() c:Disconnect() end) end
    emoteConns = {}
    emoteList = nil
    -- register() force-enabled shiftlock PAIR (mirror) mode for JJS; undo it so a
    -- re-execute or a hop to a non-JJS place doesn't leave Pantheon mirroring a
    -- game shiftlock that isn't there.
    pcall(function() shiftlock.setShiftlockMirror(false) end)
end

registry.register(JJS_IDS, JJS)

return JJS
end

_MODULES["games.evilplate"] = function()
-- Evil Plate integration.
--
-- Evil Plate is a multi-mode Roblox game; one mode is hot potato: you're handed a
-- Tool named "HotPotatoBomb" and must touch another player to pass it before your
-- timer hits 0 (the holder at 0 dies). This module auto-returns the bomb to whoever
-- passed it to you.
--
-- Feature: Hot Potato Auto-Return -- on receiving the HotPotatoBomb Tool it picks
-- the giver (an explicit reference on the bomb if one exists, else the nearest
-- player at the instant of receipt = whoever just touched you), equips it, and
-- after a short delay (beats receive-immunity) fakes the Handle's Touched back at
-- the giver via firetouchinterest -- the same touch-faking trick IY's handlekill
-- uses. If the bomb DOESN'T move after "returned ...", the game's pass is a
-- RemoteEvent instead -- swap attemptReturn() for that remote (a remote logger
-- will surface it). Detection is name-scoped to "HotPotatoBomb", so the module
-- stays idle in Evil Plate's other modes (the Tool only exists during the hot-
-- potato round) -- no separate round gating needed.
--
-- Feature: Auto Crate -- in Evil Plate's loot rounds, airdrop / supply crates
-- spawn carrying a ProximityPrompt (or ClickDetector) you normally hold E on.
-- This fires that prompt for you the instant a crate appears (workspace
-- DescendantAdded) and on a Heartbeat sweep, for anything in workspace (or
-- workspace.ActiveEvents) whose name contains airdrop / crate / supply and is
-- within click distance. Ported from the [Spec]evil_plate_crate standalone.

local registry   = require("games.registry")
local window     = require("ui.window")
local container  = require("ui.container")
local feature    = require("ui.feature")
local log        = require("core.log")
local notify     = require("ui.notify")
local friendlies = require("modules.friendlies")   -- to add the per-row "Hand Potato" button

local Players    = game:GetService("Players")
local RunService = game:GetService("RunService")
local UIS        = game:GetService("UserInputService")
local LP         = Players.LocalPlayer

-- GameId first (covers every place / VIP server), then the root PlaceId. Resolved
-- from the game URL roblox.com/games/100337093788565 (= PlaceId) -> universeId via
-- apis.roblox.com/universes/v1/places/<placeId>/universe.
local EVILPLATE_IDS = { 9324081218, 100337093788565 }   -- { GameId, PlaceId } -- Evil Plate

local EVILPLATE = {}

local CFG = {
    toolName    = "hotpotatobomb",  -- lowercased substring of the Tool name to match
    returnDelay = 0.7,              -- s before passing back / between retries (immunity buffer + not-instant)
    lobbyTeam   = "lobby",          -- lowercased substring of the team name meaning "out of the round";
                                    -- if the giver is on it (or just joined it) we stop retrying and hold
    touchTries  = 2,                -- firetouchinterest attempts before escalating to the teleport method
    giverMemory = 1.5,              -- s: how recently someone must have TOUCHED us to count as the giver.
                                    -- A pass IS a touch (captured at touch time), so a giver who instantly
                                    -- sprints off is still identified -- distance-at-receipt would miss them.
    giverRadius = 30,               -- FALLBACK when no recent touch was seen (touch didn't fire / raced after
                                    -- the bomb appeared): accept the nearest player within this many studs as
                                    -- the giver. Generous (a just-passed giver may have already fled a bit).
                                    -- The teleport stays gated by teleportMaxDist, so a far fallback giver
                                    -- only gets the subtle firetouch, never an obvious yank.
    teleportMaxDist = 18,           -- only ESCALATE to the teleport-onto-handle method if the giver is within
                                    -- this many studs -- yanking a far player onto your hand reads as lag.
                                    -- Beyond it we keep using the subtler firetouchinterest.
    maxHold     = 4,                -- s: give up retrying after this long. Stops a never-leaves-inventory
                                    -- pass (RemoteEvent game) from teleporting a now-STALE giver round
                                    -- after round -- the "potato teleports to people from old rounds" bug.
}
-- Auto Crate config -- clickRange gates how far a crate prompt may be (studs)
-- before we fire it, so we don't pop crates other players are already on.
local CRATE = {
    clickRange = 60,
}
-- Anti Plate Slip config
local SLIP = {
    platesName = "Plates",   -- workspace.<this> = the folder holding the plates
    edgeMargin = 0.1,        -- studs kept from the plate edge (0.1 = right at the edge). Raise to keep
                             -- more of you on the plate.
    pushBack   = 30,         -- inward "soft wall" strength (studs/s per stud past the edge)
    backstop   = 0.5,        -- hard-clamp if shoved this far past the edge (guarantees no walk-off)
    rayDown    = 10,         -- downward raycast length to find the plate under you
    immoveable = false,      -- "Immoveable Object": ignore push forces too (wind / forces don't release you)
    jumpBoost  = false,      -- Jump Boost: when you jump OFF A PLATE EDGE while moving, shove you in your
                             -- input direction so you carry across to the next plate
    jumpForce  = 50,         -- ...the strength of that shove (studs/s added to your velocity)
    edgeZone   = 4,          -- ...how close to the plate edge (studs) you must be for it to fire
}
local enabled      = false   -- Hot Potato Auto-Return gate
local crateEnabled = false   -- Auto Crate gate
local slipEnabled  = false   -- Anti Plate Slip gate
local pending = nil   -- { tool=, giver=, at=, lobby=, teamConn= }
local conns   = {}    -- live connections; torn down in destroy()

local function track(c) conns[#conns + 1] = c; return c end
local function teardownConns()
    for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
    conns = {}
end

-- clear the in-flight return job, disconnecting its per-bomb giver-team watcher
local function clearPending()
    if pending and pending.teamConn then pcall(function() pending.teamConn:Disconnect() end) end
    pending = nil
end

-- ---- helpers (ported from the [Spec] standalone prototype) ----

local function rootOf(char)
    if not char then return nil end
    return char:FindFirstChild("HumanoidRootPart")
        or char:FindFirstChild("Torso")
        or char:FindFirstChild("UpperTorso")
        or char:FindFirstChildWhichIsA("BasePart")
end
local function myRoot() return rootOf(LP.Character) end

local function getHandle(tool)
    local h = tool:FindFirstChild("Handle")
    if h and h:IsA("BasePart") then return h end
    for _, d in ipairs(tool:GetDescendants()) do
        if d:IsA("BasePart") then return d end
    end
    return nil
end

local function nameMatches(name)
    return type(name) == "string" and name:lower():find(CFG.toolName, 1, true) ~= nil
end

-- do we currently hold the HotPotatoBomb (Character or Backpack)?
local function iHaveBomb()
    local char = LP.Character
    if char then for _, c in ipairs(char:GetChildren()) do if c:IsA("Tool") and nameMatches(c.Name) then return true end end end
    local bp = LP:FindFirstChildOfClass("Backpack")
    if bp then for _, c in ipairs(bp:GetChildren()) do if c:IsA("Tool") and nameMatches(c.Name) then return true end end end
    return false
end

-- Who last physically TOUCHED our character, captured at touch time. A pass is a
-- touch, so this identifies the giver reliably even when they immediately sprint
-- away -- unlike "nearest player at receipt", which misses them (they're already
-- far by the time the Tool's ChildAdded fires). Set by hookTouch, read by onReceive.
local recentToucher = nil   -- { player =, at = }

local function playerFromPart(part)
    local cur = part
    while cur do
        local p = Players:GetPlayerFromCharacter(cur)
        if p then return p end
        cur = cur.Parent
    end
    return nil
end

-- our distance to a player's root (for the cosmetic teleport gate); huge if unknown
local function distTo(plr)
    local mr = myRoot()
    local tr = plr and plr.Character and rootOf(plr.Character)
    if not (mr and tr) then return math.huge end
    return (tr.Position - mr.Position).Magnitude
end

-- nearest living other player + distance (fallback giver when no touch was seen)
local function nearestPlayer()
    local best, bestD, mr = nil, math.huge, myRoot()
    if not mr then return nil, math.huge end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p.Character then
            local r   = rootOf(p.Character)
            local hum = p.Character:FindFirstChildOfClass("Humanoid")
            if r and (not hum or hum.Health > 0) then
                local d = (r.Position - mr.Position).Magnitude
                if d < bestD then best, bestD = p, d end
            end
        end
    end
    return best, bestD
end

-- explicit giver reference stored on the bomb (attribute or value object), if any
local GIVER_KEYS = { "last", "prev", "from", "giver", "owner", "holder", "thrower", "sender" }
local function keyHit(s)
    s = s:lower()
    for _, w in ipairs(GIVER_KEYS) do if s:find(w, 1, true) then return true end end
    return false
end
local function giverFromTool(tool)
    local ok, attrs = pcall(function() return tool:GetAttributes() end)
    if ok and attrs then
        for k, v in pairs(attrs) do
            if keyHit(tostring(k)) then
                log.info(("[evilplate] bomb @%s = %s (possible giver ref)"):format(tostring(k), tostring(v)))
                if type(v) == "string" then local p = Players:FindFirstChild(v); if p then return p end
                elseif type(v) == "number" then local p = Players:GetPlayerByUserId(v); if p then return p end end
            end
        end
    end
    for _, d in ipairs(tool:GetDescendants()) do
        if keyHit(d.Name) then
            if d:IsA("ObjectValue") and d.Value then
                local pl = (d.Value:IsA("Player") and d.Value) or Players:GetPlayerFromCharacter(d.Value)
                if pl then return pl end
            elseif d:IsA("StringValue") then
                local p = Players:FindFirstChild(d.Value); if p then return p end
            elseif d:IsA("IntValue") or d:IsA("NumberValue") then
                local p = Players:GetPlayerByUserId(d.Value); if p then return p end
            end
        end
    end
    return nil
end

-- one-time structure dump per receive -- console only, our live-verify aid
local function dumpTool(tool)
    log.info("[evilplate] ===== HotPotatoBomb dump =====")
    log.info(("[evilplate] Name=%s Class=%s Path=%s"):format(tool.Name, tool.ClassName, tool:GetFullName()))
    local ok, attrs = pcall(function() return tool:GetAttributes() end)
    if ok and attrs then for k, v in pairs(attrs) do log.info(("[evilplate]   @%s = %s"):format(tostring(k), tostring(v))) end end
    for _, d in ipairs(tool:GetChildren()) do log.info(("[evilplate]   child: %s (%s)"):format(d.Name, d.ClassName)) end
    local h = getHandle(tool)
    if h then
        local ti = h:FindFirstChild("TouchInterest")
        log.info(("[evilplate]   Handle=%s TouchInterest=%s CanTouch=%s"):format(
            h.Name, ti and "YES (firetouchinterest viable)" or "none (pass may be a RemoteEvent)", tostring(h.CanTouch)))
    else
        log.info("[evilplate]   NO Handle/BasePart (RequiresHandle=false? pass likely a RemoteEvent)")
    end
end

local function equip(tool)
    local char = LP.Character
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if hum and tool.Parent ~= char then pcall(function() hum:EquipTool(tool) end) end
end

-- fake Touched: try handle->giver and ourRoot->giver (no-op where no TouchInterest)
local function attemptReturn(tool, giver)
    if type(firetouchinterest) ~= "function" then
        log.warn("[evilplate] firetouchinterest unavailable in this executor"); return false
    end
    local theirRoot = rootOf(giver.Character)
    if not theirRoot then return false end
    local sources, fired = {}, false
    local h = getHandle(tool); if h then sources[#sources + 1] = h end
    local mr = myRoot();        if mr then sources[#sources + 1] = mr end
    for _, s in ipairs(sources) do
        pcall(function()
            firetouchinterest(s, theirRoot, 0)  -- begin
            firetouchinterest(s, theirRoot, 1)  -- end
            fired = true
        end)
    end
    return fired
end

-- escalation when firetouchinterest keeps leaving us holding the bomb: locally
-- teleport the giver's character onto the bomb's Handle so a REAL (not faked) Touch
-- fires. It's a client-side CFrame write -- the server snaps the giver back on its
-- next replication -- so it's only as reliable as the game trusting client touches;
-- we fire firetouchinterest in the same frame too, to cover both paths. (NOTE: live-
-- unverified -- if this still doesn't pass it, the game's pass is a RemoteEvent.)
local function attemptTeleportReturn(tool, giver)
    local handle    = getHandle(tool)
    local theirRoot = rootOf(giver.Character)
    if not (handle and theirRoot) then return false end
    pcall(function() theirRoot.CFrame = handle.CFrame end)
    if type(firetouchinterest) == "function" then
        pcall(function()
            firetouchinterest(handle, theirRoot, 0)
            firetouchinterest(handle, theirRoot, 1)
        end)
    end
    return true
end

-- the giver being on the Lobby team means they're dead / spectating ("just joined
-- that team" once they die at 0) -- there's no point bouncing the bomb back to them,
-- so we stop retrying and hold it. Substring + lower() match (team names can vary).
local function inLobby(plr)
    local t = plr and plr.Team
    return t ~= nil and type(t.Name) == "string"
        and t.Name:lower():find(CFG.lobbyTeam, 1, true) ~= nil
end

-- Manually hand the HotPotatoBomb you're holding to a chosen player (Friendlies row
-- "Hand Potato" button). Finds the bomb in your Character/Backpack, equips it, and
-- fakes its Touched at the target (same mechanism as the auto-return).
local function handPotato(plr)
    if not (plr and plr.Parent and plr.Character) then pcall(notify.warn, "Target unavailable"); return end
    if not rootOf(plr.Character) then pcall(notify.warn, "Target has no character"); return end
    local char = LP.Character
    local bp   = LP:FindFirstChildOfClass("Backpack")
    local tool
    if char then for _, c in ipairs(char:GetChildren()) do if c:IsA("Tool") and nameMatches(c.Name) then tool = c; break end end end
    if not tool and bp then for _, c in ipairs(bp:GetChildren()) do if c:IsA("Tool") and nameMatches(c.Name) then tool = c; break end end end
    if not tool then pcall(notify.warn, "You're not holding the HotPotatoBomb"); return end
    equip(tool)
    local fired = attemptReturn(tool, plr)
    if not fired then attemptTeleportReturn(tool, plr) end
    pcall(notify.info, ("Handed potato to %s"):format(plr.Name), 3)
end

-- the instant a HotPotatoBomb appears on us
local function onReceive(tool)
    if not enabled then return end
    if pending and pending.tool == tool then return end
    if pending then clearPending() end   -- a new bomb supersedes any in-flight return job
    dumpTool(tool)

    -- Giver = an explicit ref on the bomb, else whoever just TOUCHED us (the pass).
    -- We do NOT guess by who's nearest at receipt: the giver sprints off the instant
    -- they pass, so they're usually already far by the time the Tool appears -- a
    -- distance guess would miss real passes AND, if forced, fling the bomb at someone
    -- now far (looks like lag). No recent toucher = we STARTED the round holding it
    -- -> don't auto-pass.
    local giver = giverFromTool(tool)
    -- preferred: whoever just TOUCHED us (the pass), captured at touch time
    if not giver and recentToucher and (os.clock() - recentToucher.at) <= CFG.giverMemory then
        local p = recentToucher.player
        if p and p.Parent and p ~= LP then giver = p end
    end
    -- fallback: no touch seen (touch didn't fire / raced after the bomb appeared, or
    -- the pass is a RemoteEvent) -> nearest player within giverRadius. The teleport is
    -- still distance-gated, so a far fallback giver only gets the subtle firetouch.
    if not giver then
        local p, d = nearestPlayer()
        if p and d <= CFG.giverRadius then giver = p end
    end
    if not giver then
        log.info("[evilplate] no toucher and nobody within giverRadius -- started with it? not auto-passing")
        notify.info("HotPotatoBomb received (no giver to return to)", 3)
        return
    end

    -- mark pending BEFORE equipping: equip reparents the Tool (Backpack->Character),
    -- which fires Character.ChildAdded and re-enters onReceive; the pending guard at
    -- the top dedupes that re-entry so we don't process the same bomb twice.
    local now = os.clock()
    pending = { tool = tool, giver = giver, at = now, born = now, lobby = false, attempts = 0, method = "touch" }
    -- watch the giver's team: if they join Lobby ("just joined that team") mid-return,
    -- latch it sticky so we stop even if they later bounce back out of the lobby.
    pending.lobby = inLobby(giver)
    -- pcall: a Player always has GetPropertyChangedSignal in real Roblox, but never
    -- let a quirk here abort the receive (pending is already set above).
    pcall(function()
        pending.teamConn = giver:GetPropertyChangedSignal("Team"):Connect(function()
            if pending and pending.giver == giver and inLobby(giver) then
                pending.lobby = true
            end
        end)
    end)
    equip(tool)  -- Handle must be in workspace for the Touched to register
    notify.info(("HotPotatoBomb received -> returning to %s"):format(giver and giver.Name or "?"), 4)
end

local function scan(c)
    if not c then return end
    for _, d in ipairs(c:GetChildren()) do
        if d:IsA("Tool") and nameMatches(d.Name) then onReceive(d) end
    end
end

local function bindContainer(c)
    if not c then return end
    track(c.ChildAdded:Connect(function(d)
        if d:IsA("Tool") and nameMatches(d.Name) then
            onReceive(d)
            pcall(function() if friendlies.refresh then friendlies.refresh() end end)  -- bomb gained -> show Hand Potato
        end
    end))
    track(c.ChildRemoved:Connect(function(d)
        if d:IsA("Tool") and nameMatches(d.Name) then
            pcall(function() if friendlies.refresh then friendlies.refresh() end end)  -- bomb lost -> hide it
        end
    end))
end

-- record the last OTHER player whose body touched ours, captured at touch time so
-- onReceive can pick the real giver (see recentToucher). Re-hooked per character.
local function hookTouch(char)
    local hrp = rootOf(char)
    if not hrp then return end
    track(hrp.Touched:Connect(function(hit)
        local p = playerFromPart(hit)
        if p and p ~= LP then recentToucher = { player = p, at = os.clock() } end
    end))
end

local function bindCharacter(char)
    if not char then return end
    bindContainer(char)
    hookTouch(char)
    task.defer(scan, char)
    -- respawn -> bomb status likely changed; refresh the Friendlies "Hand Potato" buttons
    task.defer(function() pcall(function() if friendlies.refresh then friendlies.refresh() end end) end)
end

-- ---- Auto Crate (airdrop / supply / loot-crate opener) ----

local CRATE_WORDS = { "airdrop", "crate", "supply" }
local function crateNameHit(s)
    s = s:lower()
    for _, w in ipairs(CRATE_WORDS) do if s:find(w, 1, true) then return true end end
    return false
end

-- true if `inst` sits under a workspace child named like a crate (used by the
-- reactive DescendantAdded path, where we only have the new prompt itself)
local function isCrateDescendant(inst)
    local cur = inst.Parent
    while cur and cur ~= workspace do
        if crateNameHit(cur.Name) then return true end
        cur = cur.Parent
    end
    return false
end

-- fire one ProximityPrompt / ClickDetector, range-gated to CRATE.clickRange
local function fireCratePrompt(inst)
    if not crateEnabled then return end
    local root = myRoot()
    if not root then return end
    local adornee = inst.Parent
    local inRange = true
    if adornee and adornee:IsA("BasePart") then
        inRange = (adornee.Position - root.Position).Magnitude <= CRATE.clickRange
    end
    if not inRange then return end
    if inst:IsA("ProximityPrompt") and type(fireproximityprompt) == "function" then
        pcall(fireproximityprompt, inst, inst.HoldDuration + 0.1)
        pcall(fireproximityprompt, inst, 0)
    elseif inst:IsA("ClickDetector") and type(fireclickdetector) == "function" then
        pcall(fireclickdetector, inst)
    end
end

-- sweep workspace (+ ActiveEvents) for crate containers and fire their prompts
local function crateScan()
    if not crateEnabled then return end
    if not myRoot() then return end
    local containers = { workspace }
    local ae = workspace:FindFirstChild("ActiveEvents")
    if ae then containers[#containers + 1] = ae end
    for _, c in ipairs(containers) do
        for _, child in ipairs(c:GetChildren()) do
            if crateNameHit(child.Name) then
                for _, desc in ipairs(child:GetDescendants()) do
                    if desc:IsA("ProximityPrompt") or desc:IsA("ClickDetector") then
                        fireCratePrompt(desc)
                    end
                end
            end
        end
    end
end

-- ---- Anti Plate Slip ----
-- Keep the player from walking/sliding off the plate they're standing on. While
-- grounded on a workspace.Plates child, a soft velocity "wall" at the edge cancels
-- outward movement + gently pushes you back in (so it's not a hard teleport). It
-- releases when you're airborne (jump/fall), while you HOLD jump, or when an outside
-- FORCE INSTANCE (e.g. the wind event) is acting on you -- but NOT for player bumps
-- (those are physics collisions with no force instance), so AFK-shovers can't push
-- you off. A tiny hard backstop guarantees you can never actually walk off.

-- the plate (a workspace.Plates child) directly under the player, or nil
local function currentPlate()
    local hrp = myRoot(); if not hrp then return nil end
    local plates = workspace:FindFirstChild(SLIP.platesName); if not plates then return nil end
    local ok, res = pcall(function()
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Include
        rp.FilterDescendantsInstances = { plates }
        return workspace:Raycast(hrp.Position, Vector3.new(0, -SLIP.rayDown, 0), rp)
    end)
    return (ok and res and res.Instance) or nil
end

local AIRBORNE = {
    [Enum.HumanoidStateType.Jumping] = true, [Enum.HumanoidStateType.Freefall] = true,
    [Enum.HumanoidStateType.Flying] = true, [Enum.HumanoidStateType.FallingDown] = true,
    [Enum.HumanoidStateType.Ragdoll] = true, [Enum.HumanoidStateType.PlatformStanding] = true,
}
-- force-applying instances an event (wind etc.) attaches to push you. A player
-- ramming you is just a collision -- no such instance -- so we keep resisting them.
local FORCE_CLASS = {
    BodyVelocity = true, BodyForce = true, BodyThrust = true, BodyPosition = true,
    BodyAngularVelocity = true, BodyGyro = true, RocketPropulsion = true,
    VectorForce = true, LinearVelocity = true, AngularVelocity = true, Torque = true, AlignPosition = true,
}
local function externalForce(char)
    for _, p in ipairs(char:GetChildren()) do
        if p:IsA("BasePart") then
            for _, d in ipairs(p:GetChildren()) do
                if FORCE_CLASS[d.ClassName] then return true end
            end
        end
    end
    return false
end
-- the wind event gives all players a constant directional push; many games drive
-- that via workspace.GlobalWind, so treat a non-trivial GlobalWind as "wind active".
local function windActive()
    local ok, gw = pcall(function() return workspace.GlobalWind end)
    return ok and typeof(gw) == "Vector3" and gw.Magnitude > 1
end

local heldPlate = nil   -- the plate we're currently locking to (kept across edge ray-misses)
local function antiSlipStep()
    local char = LP.Character
    local hrp  = char and rootOf(char)
    if not hrp then heldPlate = nil; return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then heldPlate = nil; return end
    -- airborne (jumped / falling) -> release
    local ok, st = pcall(function() return hum:GetState() end)
    if ok and AIRBORNE[st] then heldPlate = nil; return end
    -- an outside force is acting on you (wind event etc.) -> release so it carries you.
    -- Detect a force INSTANCE on you OR an active GlobalWind. A player bump is a plain
    -- collision (neither), so we keep resisting AFK shovers. "Immoveable Object" skips
    -- this so pushes/wind can't move you off either (you only leave by jumping).
    if not SLIP.immoveable and (externalForce(char) or windActive()) then heldPlate = nil; return end
    -- holding jump -> don't resist, so you can hop off the edge
    if UIS:IsKeyDown(Enum.KeyCode.Space) then return end
    -- the plate under us; keep the last one if the down-ray grazes off at the edge
    local plate = currentPlate() or heldPlate
    if not plate or not plate.Parent then heldPlate = nil; return end
    heldPlate = plate

    local cf = plate.CFrame
    local lp = cf:PointToObjectSpace(hrp.Position)
    local v  = hrp.AssemblyLinearVelocity or hrp.Velocity or Vector3.new()
    local lv = cf:VectorToObjectSpace(v)
    local hx = math.max(0.1, plate.Size.X / 2 - SLIP.edgeMargin)
    local hz = math.max(0.1, plate.Size.Z / 2 - SLIP.edgeMargin)
    -- per-axis soft wall: past the edge -> inward spring; at the edge moving out -> stop
    local function axis(p, half, vel)
        if p > half then return -SLIP.pushBack * (p - half)
        elseif p < -half then return SLIP.pushBack * (-half - p)
        elseif p >= half - 0.05 and vel > 0 then return 0
        elseif p <= -half + 0.05 and vel < 0 then return 0
        end
        return vel
    end
    local nx, nz = axis(lp.X, hx, lv.X), axis(lp.Z, hz, lv.Z)
    if nx ~= lv.X or nz ~= lv.Z then
        hrp.AssemblyLinearVelocity = cf:VectorToWorldSpace(Vector3.new(nx, lv.Y, nz))
    end
    -- hard backstop: never let you end up more than `backstop` past the edge
    local clx = math.clamp(lp.X, -hx - SLIP.backstop, hx + SLIP.backstop)
    local clz = math.clamp(lp.Z, -hz - SLIP.backstop, hz + SLIP.backstop)
    if clx ~= lp.X or clz ~= lp.Z then
        local world = cf:PointToWorldSpace(Vector3.new(clx, lp.Y, clz))
        hrp.CFrame = CFrame.new(world) * (hrp.CFrame - hrp.CFrame.Position)
    end
end

-- ---- Jump Boost (plate-hop assist, companion to Anti Plate Slip) ----
-- When you jump OFF THE EDGE of a plate in the direction you're moving, add a shove in
-- that direction so you carry across to the next plate instead of dropping. The shove is
-- SLIP.jumpForce studs/s, ADDED on top of your current velocity (never slows you), one
-- shot per jump (rising edge into the Jumping state). It fires ONLY when you're within
-- SLIP.edgeZone studs of a plate edge AND heading out past THAT edge -- so a jump from
-- the middle of a plate (or jumping inward) gets nothing. Only the horizontal is boosted.

-- true if hrp sits within edgeZone of a plate edge AND moveDir heads out past that edge
local function jumpingOffEdge(plate, hrp, moveDir)
    local cf = plate.CFrame
    local lp = cf:PointToObjectSpace(hrp.Position)     -- our spot on the plate (local)
    local lm = cf:VectorToObjectSpace(moveDir)         -- input direction in plate space
    local halfX, halfZ = plate.Size.X / 2, plate.Size.Z / 2
    local zone = SLIP.edgeZone
    if (halfX - lp.X) <= zone and lm.X >  0.1 then return true end   -- off the +X edge
    if (halfX + lp.X) <= zone and lm.X < -0.1 then return true end   -- off the -X edge
    if (halfZ - lp.Z) <= zone and lm.Z >  0.1 then return true end   -- off the +Z edge
    if (halfZ + lp.Z) <= zone and lm.Z < -0.1 then return true end   -- off the -Z edge
    return false
end

local wasJumping = false
local function jumpBoostStep()
    local char = LP.Character
    local hrp  = char and rootOf(char)
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if not (hrp and hum) then wasJumping = false; return end
    local ok, stt = pcall(function() return hum:GetState() end)
    local jumping = ok and (stt == Enum.HumanoidStateType.Jumping)
    if jumping and not wasJumping then          -- rising edge: the jump just started
        local mdir  = hum.MoveDirection
        local plate = currentPlate()
        if plate and mdir.Magnitude > 0.1 and jumpingOffEdge(plate, hrp, mdir) then
            local v    = hrp.AssemblyLinearVelocity or hrp.Velocity or Vector3.new()
            local push = mdir.Unit * SLIP.jumpForce
            hrp.AssemblyLinearVelocity = Vector3.new(v.X + push.X, v.Y, v.Z + push.Z)
        end
    end
    wasJumping = jumping
end

-- drain pending returns from Heartbeat -- NEVER task.wait inside the receive
-- signal callback on Wave (coroutine may not resume); queue + drain here instead.
-- The same Heartbeat also drives the Auto Crate sweep + Anti Plate Slip.
local function onHeartbeat()
    if crateEnabled then crateScan() end
    if slipEnabled then antiSlipStep() end
    if slipEnabled and SLIP.jumpBoost then jumpBoostStep() end
    if not pending then return end
    if not enabled then clearPending(); return end

    local job  = pending
    local char = LP.Character
    local bp   = LP:FindFirstChildOfClass("Backpack")

    -- success / done: keep retrying ONLY until the bomb actually leaves our inventory
    local have = job.tool and (job.tool.Parent == char or job.tool.Parent == bp)
    if not have then
        notify.success("Bomb passed -- left your inventory", 3)
        log.info("[evilplate] bomb left inventory -- done")
        clearPending(); return
    end

    -- held too long: the giver ref is stale (the pass is probably a RemoteEvent so
    -- the bomb never leaves us). Stop -- otherwise we'd keep teleporting a giver
    -- from an old round onto the handle forever (the obvious "potato jumps to people
    -- from previous rounds" tell).
    if (os.clock() - (job.born or 0)) > CFG.maxHold then
        log.info("[evilplate] held > maxHold -- giving up (stale giver / RemoteEvent pass)")
        clearPending(); return
    end

    -- giver left the game entirely: nothing to return to, stop and hold
    if not job.giver or job.giver.Parent == nil then
        log.info("[evilplate] giver left game -- stop retrying, holding bomb")
        clearPending(); return
    end

    -- giver is on (or just joined) the Lobby team -> stop retrying and hold the bomb
    if job.lobby or inLobby(job.giver) then
        notify.warn(("Giver %s in Lobby -- holding bomb"):format(job.giver.Name))
        log.info("[evilplate] giver on Lobby team -- stop retrying, holding bomb")
        clearPending(); return
    end

    -- throttle retries to returnDelay (beats receive-immunity; no per-frame spam)
    if (os.clock() - job.at) < CFG.returnDelay then return end
    -- giver mid-respawn (no character right now): wait, don't give up
    if not job.giver.Character then job.at = os.clock(); return end

    -- escalate: firetouchinterest tried touchTries times and we STILL hold the bomb ->
    -- mark for the teleport-onto-handle method to force a real touch
    if job.method == "touch" and job.attempts >= CFG.touchTries then
        job.method = "teleport"
        log.info("[evilplate] escalating to teleport-onto-handle for " .. job.giver.Name)
    end

    -- Only actually teleport when the giver is close enough that pulling them onto
    -- the handle reads as a normal contact pass. If they've fled, stay on the subtle
    -- firetouch -- a long-range yank would look like lag.
    local ok, used
    if job.method == "teleport" and distTo(job.giver) <= CFG.teleportMaxDist then
        used = "teleport"; ok = attemptTeleportReturn(job.tool, job.giver)
    else
        used = "touch";    ok = attemptReturn(job.tool, job.giver)
    end
    job.attempts = job.attempts + 1
    if ok then
        log.info(("[evilplate] %s attempt -> %s (if bomb stays, pass = RemoteEvent)"):format(used, job.giver.Name))
    else
        log.warn("[evilplate] " .. used .. " attempt failed (giver root missing?)")
    end
    job.at = os.clock()  -- schedule next retry; loop continues until the bomb leaves inventory
end

function EVILPLATE.register()
    local buildTag = tostring(rawget(_G, "PANTHEON_BUILD") or "?")
    pcall(function() notify.success("Evil Plate registered (build " .. buildTag .. ")", 6) end)
    log.info("[evilplate] register on PlaceId=" .. tostring(game.PlaceId) .. " GameId=" .. tostring(game.GameId))

    -- detection: backpack + character (rebind on respawn / backpack rebuild). Wired
    -- once at register; onReceive/onHeartbeat gate on `enabled`. destroy() unwires.
    bindContainer(LP:FindFirstChildOfClass("Backpack"))
    track(LP.ChildAdded:Connect(function(c) if c:IsA("Backpack") then bindContainer(c) end end))
    bindCharacter(LP.Character)
    track(LP.CharacterAdded:Connect(bindCharacter))
    track(RunService.Heartbeat:Connect(onHeartbeat))

    -- instant crate reaction: fire any prompt/detector that spawns inside a crate
    -- (the Heartbeat sweep is the fallback for ones present before we connected)
    track(workspace.DescendantAdded:Connect(function(desc)
        if not crateEnabled then return end
        if (desc:IsA("ProximityPrompt") or desc:IsA("ClickDetector")) and isCrateDescendant(desc) then
            task.defer(fireCratePrompt, desc)
        end
    end))

    local box = container.new(window.parent(), "Evil Plate")
    box:add(feature.declare({
        id          = "evilplate.hotpotato_return",
        name        = "Hot Potato Auto-Return",
        description = "When you're passed the HotPotatoBomb, automatically passes it back to whoever gave it to you. Picks the giver from a reference on the bomb if one exists, else the nearest player at the instant you received it (whoever touched you). Equips the bomb and fakes its Touched back at them, retrying every \"Return delay\" seconds until the bomb actually leaves your inventory. If firetouchinterest doesn't pass it after a couple tries, it escalates to teleporting the giver onto the bomb's Handle to force a real touch. Stops (and just holds the bomb) if the giver moves to the Lobby team -- i.e. they died / left the round -- or leaves the game. If the bomb never leaves you even after the teleport method, the game passes via a RemoteEvent instead -- say so and it gets switched.",
        default     = false,
        onToggle    = function(v)
            enabled = v and true or false
            -- enabling mid-hold: re-scan so a bomb you're already holding returns too
            if enabled then
                task.defer(function()
                    scan(LP.Character)
                    scan(LP:FindFirstChildOfClass("Backpack"))
                end)
            end
        end,
        settings    = {
            { type = "slider", name = "Return delay (s)", key = "delay",
              min = 0, max = 2, step = 0.05, default = CFG.returnDelay,
              onChange = function(v) CFG.returnDelay = v end },
        },
    }).root)

    box:add(feature.declare({
        id          = "evilplate.auto_crate",
        name        = "Auto Crate",
        description = "Auto-opens airdrop / supply crates. Instantly fires the ProximityPrompt (or ClickDetector) on anything in workspace -- or workspace.ActiveEvents -- whose name contains \"airdrop\", \"crate\" or \"supply\", the moment it spawns and on a continuous sweep. Only fires prompts within the click distance below, so crates other players are already opening across the map are left alone.",
        default     = false,
        onToggle    = function(v) crateEnabled = v and true or false end,
        settings    = {
            { type = "slider", name = "Click distance (studs)", key = "click_range",
              min = 5, max = 100, step = 1, default = CRATE.clickRange,
              onChange = function(v) CRATE.clickRange = v end },
        },
    }).root)

    box:add(feature.declare({
        id          = "evilplate.anti_plate_slip",
        name        = "Anti Plate Slip",
        description = "Holds you onto whatever plate (workspace.Plates child) you're standing on so you can't accidentally walk or slide off the edge -- a soft velocity 'wall' at the edge cancels your outward movement and gently pushes you back (not a hard teleport). It RELEASES when you go airborne (jump/fall), while you HOLD jump (so you can hop plate to plate), or when an outside FORCE is acting on you (e.g. the wind event) -- but NOT when another player just bumps you, so AFK shovers can't push you off. It re-enables itself the instant you land back on a plate. A tiny backstop guarantees you can never fully walk off. Turn on \"Jump boost\" to get a shove in your movement direction when you jump off the EDGE of a plate -- only near the edge and heading outward, so middle-of-plate jumps do nothing -- set how hard with \"Jump force\" and how close to the edge counts as the edge with \"Jump edge zone\". Handy for clearing the gap to the next plate.",
        default     = false,
        onToggle    = function(v) slipEnabled = v and true or false end,
        settings    = {
            { type = "slider", name = "Edge margin (studs)", key = "edge_margin",
              min = 0.1, max = 6, step = 0.1, default = SLIP.edgeMargin,
              onChange = function(v) SLIP.edgeMargin = v end },
            { type = "slider", name = "Push strength", key = "push_strength",
              min = 1, max = 80, step = 1, default = SLIP.pushBack,
              onChange = function(v) SLIP.pushBack = v end },
            { type = "toggle", name = "Jump boost (push off plates)", key = "jump_boost", default = false,
              onChange = function(v) SLIP.jumpBoost = v and true or false end },
            { type = "slider", name = "Jump force", key = "jump_force",
              min = 0, max = 200, step = 5, default = SLIP.jumpForce,
              onChange = function(v) SLIP.jumpForce = v end },
            { type = "slider", name = "Jump edge zone (studs)", key = "jump_edge_zone",
              min = 1, max = 20, step = 1, default = SLIP.edgeZone,
              onChange = function(v) SLIP.edgeZone = v end },
            { type = "toggle", name = "Immoveable Object", key = "immoveable", default = false,
              onChange = function(v) SLIP.immoveable = v and true or false end },
        },
    }).root)

    -- Friendlies menu: a "Hand Potato" button next to each player NOT on the Lobby team.
    pcall(function()
        if friendlies.addPlayerAction then
            friendlies.addPlayerAction({
                scope     = EVILPLATE_IDS,
                label     = "Hand Potato",
                predicate = function(p) return iHaveBomb() and not inLobby(p) end,
                onClick   = function(p) handPotato(p) end,
            })
        end
    end)

    log.info("[evilplate] module registered -- Hot Potato Auto-Return + Auto Crate + Anti Plate Slip + Hand Potato")
end

-- Called by init.lua shutdown (Auto Re-Execute / re-execute). register() reruns on
-- every boot, so every connection it made must be undone here or they stack across
-- teleports (see feedback_pantheon_reexec_leaks). The feature row + its keybind are
-- torn down by window/keybinds.destroy; the connections + module state are ours.
function EVILPLATE.destroy()
    enabled      = false
    crateEnabled = false
    slipEnabled  = false
    clearPending()
    teardownConns()
end

registry.register(EVILPLATE_IDS, EVILPLATE)

return EVILPLATE
end

_MODULES["games.gakuran"] = function()
-- Gakuran (PlaceId 128736949265057, GameId 9199655655) combat integration.
--
-- Registered into the game registry; its container only appears when you're in
-- Gakuran (init.lua calls registry.current().register() gated on PlaceId/GameId),
-- so none of this runs -- or costs perf -- in any other game.
--
-- Ported from the standalone [Spec] Gakuran Combat script. Watches nearby enemies'
-- animations and reacts: incoming M1 -> hold F (perfect block), incoming heavy (M2)
-- -> tap Q (dodge). Plus grip-spam (auto M1 while you grip), guard-break (M1 into a
-- blocker -> R heavy), and click-cancel (don't punch into a charging heavy).
-- Inputs: M1=LClick, heavy=R, block=F(hold), dodge=Q, blink=RClick. EHit/M2Success/
-- Guardbreak are hit-REACTIONS (not triggers) -- including them made it react to your
-- own landed hits.
--
-- REACH: flat. Trigger distance is stableHeight x 2.6 (the confirmed-correct value).
-- The old per-size Auto-Reach learner is gone. Range still scales with the opponent's
-- body size (bigger enemy -> bigger reach) via their measured height; 2.6 is fixed.
--
-- HIT TIMING is size-aware. Small players swing faster, so the same anim lands sooner
-- in wall-clock. We read the LIVE AnimationTrack (TimePosition / Speed) for the exact
-- time-to-impact; when the game does NOT scale the track Speed by size (Speed ~= 1) we
-- fold in a body-size correction so a small attacker still gets a shorter windup. See
-- scheduleReaction. Optional Marker Hit Timing (game:GetObjects) refines the exact
-- contact frame when the executor allows it -- but NOTHING here depends on GetObjects.
--
-- LEARNING (executor-native, no GetObjects):
--   * Unknown attack anims are classified from the LIVE track LENGTH -- short -> M1,
--     unknown attacks default to M1 (parry) and only DODGE a confirmed heavy (static DB
--     or an asset name that says M2/heavy), so basic M1s never get mis-dodged.
--   * A DAMAGE-DRIVEN RECLASSIFIER watches for damage/block-hits: any correctable enemy anim
--     that plays and is then followed (within confirmWindow) by us taking a hit while it was
--     in range is blamed and (re)classified an attack. Getting hit is ground truth, so this
--     runs even off your locked target and regardless of the parry facing/reach gates. Unknown
--     ids learn on the FIRST hit; an anim MIS-FILED as movement noise (a dash/idle whose real
--     hit only shows up once you stop dodging it) is overridden only after CORRECT_HITS hits,
--     so a coincidental dash/emote can't be flipped. A length gate keeps long idles/emotes out.
--   * Anims you've already LOGGED are prefetched through the name-scan at register and
--     classified by their real asset name -- never force-parried.
--   Learned classes persist to disk + settings and are announced.
--
-- CARRY: "Carrying" (71363952449940) plays on BOTH the carrier AND the person being
-- carried -- it is NOT a grip. It lives in CARRY_SELF, never triggers grip-spam, and
-- while it's active grip-spam is force-stopped. Only the real Grip (108723830385066)
-- spams M1.

local registry   = require("games.registry")
local window     = require("ui.window")
local container  = require("ui.container")
local feature    = require("ui.feature")
local components = require("ui.components")
local persist    = require("core.persist")
local log        = require("core.log")
